css:
.cpf-equity-underwater{box-sizing:border-box;width:100%;max-width:400px;min-width:0;container-type:inline-size;background:#0B0F17;border:1px solid #1C2432;border-radius:8px;padding:9px 10px 8px;color:#8B98B0;font:9px/1.35 ui-monospace,Menlo,Consolas,monospace;font-variant-numeric:tabular-nums;outline:none}
.cpf-equity-underwater *{box-sizing:border-box}
.cpf-equity-underwater:focus-visible{border-color:#3A5BA0;box-shadow:0 0 0 1px #3A5BA0}
.cpf-equity-underwater-hd{display:flex;justify-content:space-between;align-items:baseline;gap:6px;margin-bottom:6px}
.cpf-equity-underwater-t{font:700 10px/1.2 system-ui,-apple-system,Segoe UI,sans-serif;color:#E4EBF7;letter-spacing:.05em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.cpf-equity-underwater-t b{display:block;font:500 7.5px/1.4 ui-monospace,Menlo,Consolas,monospace;color:#5B6883;letter-spacing:.08em}
.cpf-equity-underwater-nav{font-size:13px;font-weight:700;color:#E4EBF7;text-align:right;white-space:nowrap}
.cpf-equity-underwater-nav small{display:block;font-size:8px;font-weight:500}
.cpf-equity-underwater-kpi{display:grid;grid-template-columns:repeat(6,1fr);border:1px solid #1A2230;border-radius:4px;margin-bottom:7px}
.cpf-equity-underwater-kpi div{padding:3px 4px;border-left:1px solid #1A2230;min-width:0}
.cpf-equity-underwater-kpi div:first-child{border-left:0}
.cpf-equity-underwater-kpi span{display:block;font-size:6.5px;letter-spacing:.08em;color:#4B5772;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.cpf-equity-underwater-kpi b{display:block;font-size:9.5px;font-weight:600;color:#D6DFEF;text-align:right;white-space:nowrap}
.cpf-equity-underwater-plots{position:relative;cursor:crosshair;touch-action:none}
.cpf-equity-underwater-top{position:relative;height:92px;border-bottom:1px solid #243047}
.cpf-equity-underwater-bot{position:relative;height:38px;margin-top:1px}
.cpf-equity-underwater-svg{position:absolute;inset:0;width:100%;height:100%;display:block;overflow:visible}
.cpf-equity-underwater-top .cpf-equity-underwater-svg{animation:cpf-equity-underwater-wipe .9s cubic-bezier(.3,.7,.2,1) both}
.cpf-equity-underwater-grid line,.cpf-equity-underwater-grid2 line{stroke:#161D29;stroke-width:1;vector-effect:non-scaling-stroke}
.cpf-equity-underwater-ep{fill:rgba(255,92,108,.07)}
.cpf-equity-underwater-area{fill:rgba(110,168,255,.10)}
.cpf-equity-underwater-hwm{fill:none;stroke:#F5B942;stroke-width:1;stroke-dasharray:3 2;vector-effect:non-scaling-stroke;opacity:.8}
.cpf-equity-underwater-line{fill:none;stroke:#6EA8FF;stroke-width:1.4;vector-effect:non-scaling-stroke;stroke-linejoin:round}
.cpf-equity-underwater-uw{fill:rgba(255,92,108,.38);stroke:#FF5C6C;stroke-width:1;vector-effect:non-scaling-stroke}
.cpf-equity-underwater-cx,.cpf-equity-underwater-cx2{stroke:#C9D4E8;stroke-width:1;stroke-dasharray:2 2;vector-effect:non-scaling-stroke;opacity:.7}
.cpf-equity-underwater-dot{position:absolute;width:7px;height:7px;margin:-3.5px 0 0 -3.5px;border-radius:50%;background:#6EA8FF;border:1.5px solid #0B0F17;box-shadow:0 0 0 1px #6EA8FF;pointer-events:none}
.cpf-equity-underwater-yl{position:absolute;right:2px;font-size:7px;color:#5B6883;background:rgba(11,15,23,.78);padding:0 2px;pointer-events:none}
.cpf-equity-underwater-y1{top:0}
.cpf-equity-underwater-y0{bottom:1px}
.cpf-equity-underwater-z0{top:0}
.cpf-equity-underwater-z1{bottom:0;color:#FF7F8B}
.cpf-equity-underwater-lg{position:absolute;left:2px;top:0;font-size:7px;letter-spacing:.06em;pointer-events:none}
.cpf-equity-underwater-lg em{font-style:normal}
.cpf-equity-underwater-lgn{color:#6EA8FF}
.cpf-equity-underwater-lgh{color:#F5B942;margin-left:5px}
.cpf-equity-underwater-uwl{position:absolute;left:2px;bottom:0;font-size:6.5px;letter-spacing:.08em;color:#6B4550;pointer-events:none}
.cpf-equity-underwater-xax{position:relative;height:11px;font-size:7px;color:#5B6883}
.cpf-equity-underwater-xax span{position:absolute;top:1px;transform:translateX(-50%);white-space:nowrap}
.cpf-equity-underwater-read{display:flex;flex-wrap:wrap;gap:2px 8px;padding:4px 5px;margin:3px 0 6px;background:#0F1420;border:1px solid #1A2230;border-radius:3px;font-size:8.5px;color:#8B98B0;min-height:19px}
.cpf-equity-underwater-read b{color:#E4EBF7;font-weight:600}
.cpf-equity-underwater-tb{width:100%;border-collapse:collapse;font-size:8px}
.cpf-equity-underwater-tb th{font-size:6.5px;letter-spacing:.08em;color:#4B5772;font-weight:500;text-align:left;padding:2px 3px;border-bottom:1px solid #1A2230}
.cpf-equity-underwater-tb td{padding:2.5px 3px;border-bottom:1px solid #121926;color:#AEB9CD;white-space:nowrap}
.cpf-equity-underwater-tb tbody tr{cursor:pointer}
.cpf-equity-underwater-tb tbody tr:hover td{background:#111827}
.cpf-equity-underwater-tb tbody tr.cpf-equity-underwater-sel td{background:#172238;box-shadow:inset 0 1px #2A3D63,inset 0 -1px #2A3D63}
.cpf-equity-underwater-tb .cpf-equity-underwater-r{text-align:right}
.cpf-equity-underwater .cpf-equity-underwater-up{color:#25E07A}
.cpf-equity-underwater .cpf-equity-underwater-dn{color:#FF5C6C}
.cpf-equity-underwater .cpf-equity-underwater-open{color:#F5B942}
@keyframes cpf-equity-underwater-wipe{from{clip-path:inset(0 100% 0 0)}to{clip-path:inset(0 0 0 0)}}
@container (max-width: 330px){.cpf-equity-underwater-kpi{grid-template-columns:repeat(3,1fr)}.cpf-equity-underwater-kpi div:nth-child(4){border-left:0}.cpf-equity-underwater-kpi div:nth-child(n+4){border-top:1px solid #1A2230}}
@media (prefers-reduced-motion: reduce){.cpf-equity-underwater-top .cpf-equity-underwater-svg{animation:none}}

