var P = 'cpf-equity-underwater';
function q(s) { return root.querySelector('.' + P + '-' + s); }
var seed = 91021;
function rnd() { seed = seed + 0x6D2B79F5 | 0; var t = Math.imul(seed ^ seed >>> 15, 1 | seed); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; }
function gauss() { var u = 1 - rnd(), v = rnd(); return Math.sqrt(-2 * Math.log(u)) * Math.cos(6.283185307 * v); }
var MON = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
var N = 756, RF = 0.0425, W = 300, H = 90, UH = 36;
var dates = [], d = new Date(Date.UTC(2026, 8, 23));
while (dates.length < N) { var wd = d.getUTCDay(); if (wd !== 0 && wd !== 6) dates.push(new Date(d.getTime())); d.setUTCDate(d.getUTCDate() - 1); }
dates.reverse();
function fd(t) { var x = dates[t]; return ('0' + x.getUTCDate()).slice(-2) + ' ' + MON[x.getUTCMonth()] + ' ' + String(x.getUTCFullYear()).slice(2); }
var nav = [100], hwm = [100], dd = [0], ret = [];
for (var i = 1; i < N; i++) {
  var mu = 0.00085;
  if (i > 150 && i < 262) mu = -0.0009;
  if (i > 505 && i < 560) mu = -0.0014;
  if (i > 700) mu = -0.0001;
  var r = mu + 0.0074 * gauss();
  ret.push(r);
  nav.push(nav[i - 1] * (1 + r));
  hwm.push(Math.max(hwm[i - 1], nav[i]));
  dd.push(nav[i] / hwm[i] - 1);
}
var m = 0, s2 = 0, k;
for (k = 0; k < ret.length; k++) m += ret[k];
m /= ret.length;
for (k = 0; k < ret.length; k++) s2 += (ret[k] - m) * (ret[k] - m);
var vol = Math.sqrt(s2 / (ret.length - 1)) * Math.sqrt(252);
var cagr = Math.pow(nav[N - 1] / nav[0], 252 / (N - 1)) - 1;
var shp = (m * 252 - RF) / vol;
var mdd = 0, mddI = 0;
for (k = 0; k < N; k++) if (dd[k] < mdd) { mdd = dd[k]; mddI = k; }
var tuw = 0;
for (k = N - 1; k >= 0 && dd[k] < 0; k--) tuw++;
/* drawdown episodes: peak -> trough -> recovery (first close back at the prior HWM) */
var eps = [], cur = null;
for (k = 1; k < N; k++) {
  if (dd[k] < 0 && !cur) cur = { pk: k - 1, tr: k, rc: -1 };
  if (cur) {
    if (dd[k] < dd[cur.tr]) cur.tr = k;
    if (dd[k] === 0) { cur.rc = k; eps.push(cur); cur = null; }
  }
}
if (cur) eps.push(cur);
eps.sort(function (a, b) { return dd[a.tr] - dd[b.tr]; });
eps = eps.slice(0, 4);
function pct(v, dp) { return (v > 0 ? '+' : v < 0 ? '−' : '') + Math.abs(v * 100).toFixed(dp == null ? 2 : dp) + '%'; }
var lo = Infinity, hi = -Infinity;
for (k = 0; k < N; k++) { lo = Math.min(lo, nav[k]); hi = Math.max(hi, hwm[k]); }
var pad = (hi - lo) * 0.06; lo -= pad; hi += pad;
function X(t) { return t / (N - 1) * W; }
function Y(v) { return 2 + (hi - v) / (hi - lo) * (H - 4); }
function U(v) { return 1 + v / mdd * (UH - 3); }
var ln = '', hw = '', uw = 'M0,1';
for (k = 0; k < N; k++) {
  var x = X(k).toFixed(2);
  ln += (k ? ' L' : 'M') + x + ',' + Y(nav[k]).toFixed(2);
  hw += (k ? ' L' : 'M') + x + ',' + Y(hwm[k]).toFixed(2);
  uw += ' L' + x + ',' + U(dd[k]).toFixed(2);
}
q('line').setAttribute('d', ln);
q('area').setAttribute('d', ln + ' L' + W + ',' + H + ' L0,' + H + ' Z');
q('hwm').setAttribute('d', hw);
q('uw').setAttribute('d', uw + ' L' + W + ',1 Z');
q('y1').textContent = hi.toFixed(1);
q('y0').textContent = lo.toFixed(1);
q('z1').textContent = pct(mdd, 1);
/* year ticks */
var NS = 'http://www.w3.org/2000/svg', g1 = q('grid'), g2 = q('grid2'), xax = q('xax'), xh = '';
for (k = 1; k < N; k++) {
  if (dates[k].getUTCFullYear() !== dates[k - 1].getUTCFullYear()) {
    var gx = X(k);
    [[g1, H], [g2, UH]].forEach(function (p) {
      var l = document.createElementNS(NS, 'line');
      l.setAttribute('x1', gx); l.setAttribute('x2', gx); l.setAttribute('y1', 0); l.setAttribute('y2', p[1]);
      p[0].appendChild(l);
    });
    xh += '<span style="left:' + (gx / W * 100).toFixed(2) + '%">' + dates[k].getUTCFullYear() + '</span>';
  }
}
xax.innerHTML = xh;
[0.25, 0.5, 0.75].forEach(function (f) {
  var l = document.createElementNS(NS, 'line');
  l.setAttribute('x1', 0); l.setAttribute('x2', W); l.setAttribute('y1', H * f); l.setAttribute('y2', H * f);
  g1.appendChild(l);
});
var chg = nav[N - 1] / nav[N - 2] - 1;
q('nav').innerHTML = nav[N - 1].toFixed(2) + '<small class="' + P + '-' + (chg >= 0 ? 'up' : 'dn') + '">' + (chg >= 0 ? '▲ ' : '▼ ') + pct(chg) + ' 1D</small>';
function kv(key, txt, cls) { var b = root.querySelector('[data-k="' + key + '"]'); b.textContent = txt; if (cls) b.className = P + '-' + cls; }
kv('cagr', pct(cagr), cagr >= 0 ? 'up' : 'dn');
kv('vol', (vol * 100).toFixed(2) + '%');
kv('shp', shp.toFixed(2));
kv('mdd', pct(mdd), 'dn');
kv('cdd', pct(dd[N - 1]), dd[N - 1] < 0 ? 'dn' : 'up');
kv('tuw', tuw ? tuw + 'd' : 'at HWM', tuw ? 'open' : 'up');
var tb = root.querySelector('.' + P + '-tb tbody'), rows = '';
eps.forEach(function (e, n) {
  var days = (e.rc < 0 ? N - 1 : e.rc) - e.pk;
  rows += '<tr data-e="' + n + '"><td>' + (n + 1) + '</td><td>' + fd(e.pk) + '</td><td>' + fd(e.tr) + '</td><td' + (e.rc < 0 ? ' class="' + P + '-open">open' : '>' + fd(e.rc)) + '</td><td class="' + P + '-r ' + P + '-dn">' + pct(dd[e.tr]) + '</td><td class="' + P + '-r">' + days + '</td></tr>';
});
tb.innerHTML = rows;
var ep = q('ep'), selE = -1;
function showEp(n) {
  selE = n;
  [].forEach.call(tb.children, function (tr, j) { tr.classList.toggle(P + '-sel', j === n); });
  if (n < 0) { ep.setAttribute('width', 0); return; }
  var e = eps[n], end = e.rc < 0 ? N - 1 : e.rc;
  ep.setAttribute('x', X(e.pk)); ep.setAttribute('width', Math.max(0.6, X(end) - X(e.pk)));
}
var idx = N - 1, cx = q('cx'), cx2 = q('cx2'), dot = q('dot'), rd = q('read');
function paint() {
  var x = X(idx);
  cx.setAttribute('x1', x); cx.setAttribute('x2', x);
  cx2.setAttribute('x1', x); cx2.setAttribute('x2', x);
  dot.style.left = (x / W * 100) + '%';
  dot.style.top = (Y(nav[idx]) / H * 100) + '%';
  var r0 = idx ? nav[idx] / nav[idx - 1] - 1 : 0;
  rd.innerHTML = '<b>' + fd(idx) + '</b><span>NAV <b>' + nav[idx].toFixed(2) + '</b></span><span>HWM <b>' + hwm[idx].toFixed(2) + '</b></span><span>DD <b class="' + P + '-' + (dd[idx] < 0 ? 'dn' : 'up') + '">' + pct(dd[idx]) + '</b></span><span>1D <b class="' + P + '-' + (r0 >= 0 ? 'up' : 'dn') + '">' + pct(r0) + '</b></span>';
}
tb.addEventListener('click', function (ev) {
  var tr = ev.target.closest('tr'); if (!tr) return;
  var n = +tr.getAttribute('data-e');
  if (n === selE) { showEp(-1); } else { showEp(n); idx = eps[n].tr; paint(); }
});
var plots = q('plots');
function fromPointer(ev) {
  var rc = plots.getBoundingClientRect(); if (!rc.width) return;
  idx = Math.max(0, Math.min(N - 1, Math.round((ev.clientX - rc.left) / rc.width * (N - 1))));
  paint();
}
plots.addEventListener('pointermove', fromPointer);
plots.addEventListener('pointerdown', fromPointer);
root.addEventListener('keydown', function (ev) {
  var st = ev.shiftKey ? 21 : 1, k2 = ev.key;
  if (k2 === 'ArrowLeft') idx = Math.max(0, idx - st);
  else if (k2 === 'ArrowRight') idx = Math.min(N - 1, idx + st);
  else if (k2 === 'Home') idx = 0;
  else if (k2 === 'End') idx = N - 1;
  else if (k2 === 'ArrowDown' || k2 === 'ArrowUp') {
    var n = selE + (k2 === 'ArrowDown' ? 1 : -1);
    if (n < 0) n = eps.length - 1; if (n >= eps.length) n = 0;
    showEp(n); idx = eps[n].tr;
  } else if (k2 === 'Escape') { showEp(-1); idx = N - 1; }
  else return;
  ev.preventDefault(); paint();
});
paint();

css:
.cpf-monthly-heatmap{box-sizing:border-box;width:100%;max-width:400px;min-width:0;container-type:inline-size;background:#0B0F17;border:1px solid #1C2432;border-radius:8px;padding:9px 9px 8px;color:#8B98B0;font:9px/1.35 ui-monospace,Menlo,Consolas,monospace;font-variant-numeric:tabular-nums;outline:none}
.cpf-monthly-heatmap *{box-sizing:border-box}
.cpf-monthly-heatmap:focus-visible{border-color:#3A5BA0;box-shadow:0 0 0 1px #3A5BA0}
.cpf-monthly-heatmap-hd{display:flex;justify-content:space-between;align-items:flex-start;gap:6px;margin-bottom:6px}
.cpf-monthly-heatmap-t{font:700 10px/1.2 system-ui,-apple-system,Segoe UI,sans-serif;color:#E4EBF7;letter-spacing:.05em;min-width:0}
.cpf-monthly-heatmap-t b{display:block;font:500 7px/1.4 ui-monospace,Menlo,Consolas,monospace;color:#5B6883;letter-spacing:.06em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.cpf-monthly-heatmap-seg{display:flex;border:1px solid #243047;border-radius:3px;overflow:hidden;flex:none}
.cpf-monthly-heatmap-seg button{font:600 7.5px/1 ui-monospace,Menlo,Consolas,monospace;letter-spacing:.06em;color:#6B7890;background:transparent;border:0;border-left:1px solid #243047;padding:4px 5px;cursor:pointer}
.cpf-monthly-heatmap-seg button:first-child{border-left:0}
.cpf-monthly-heatmap-seg button:hover{color:#C9D4E8}
.cpf-monthly-heatmap-seg .cpf-monthly-heatmap-on{background:#1B2A45;color:#E4EBF7}
.cpf-monthly-heatmap-grid{display:grid;grid-template-columns:22px repeat(12,minmax(0,1fr)) 28px;gap:1px;background:#0B0F17}
.cpf-monthly-heatmap-h{font-size:6.5px;letter-spacing:.06em;color:#4B5772;text-align:center;padding:1px 0 2px}
.cpf-monthly-heatmap-y{font-size:7.5px;color:#8B98B0;display:flex;align-items:center}
.cpf-monthly-heatmap-c{height:16px;display:flex;align-items:center;justify-content:center;font-size:7.4px;letter-spacing:-.03em;color:#C9D4E8;border-radius:1.5px;cursor:pointer;white-space:nowrap;overflow:hidden;transition:background-color .25s ease;outline:1px solid transparent;outline-offset:-1px}
.cpf-monthly-heatmap-c:hover{outline-color:#5B6883}
.cpf-monthly-heatmap-c.cpf-monthly-heatmap-sel{outline:1.5px solid #F2F6FF;outline-offset:-1px;position:relative;z-index:1}
.cpf-monthly-heatmap-na{color:#2C3547;cursor:default}
.cpf-monthly-heatmap-yr{font-weight:700;border-left:1px solid #2A3650}
.cpf-monthly-heatmap-lg{display:flex;align-items:center;gap:5px;margin:6px 0 5px;font-size:7px;color:#5B6883}
.cpf-monthly-heatmap-bar{flex:0 0 90px;height:5px;border-radius:2px;background:linear-gradient(90deg,rgba(255,92,108,.85),rgba(255,92,108,.12) 48%,#141A26 50%,rgba(37,224,122,.12) 52%,rgba(37,224,122,.85))}
.cpf-monthly-heatmap-mode{font-style:normal;margin-left:auto;letter-spacing:.06em;color:#6B7890}
.cpf-monthly-heatmap-det{display:flex;flex-wrap:wrap;gap:2px 8px;padding:4px 5px;background:#0F1420;border:1px solid #1A2230;border-radius:3px;font-size:8.3px;min-height:19px}
.cpf-monthly-heatmap-det b{color:#E4EBF7;font-weight:600}
.cpf-monthly-heatmap-ft{display:grid;grid-template-columns:repeat(4,1fr);gap:1px;margin-top:6px;background:#1A2230;border:1px solid #1A2230;border-radius:3px;overflow:hidden}
.cpf-monthly-heatmap-ft div{background:#0B0F17;padding:3px 4px;min-width:0}
.cpf-monthly-heatmap-ft span{display:block;font-size:6.5px;letter-spacing:.08em;color:#4B5772;white-space:nowrap}
.cpf-monthly-heatmap-ft b{display:block;font-size:9px;font-weight:600;color:#D6DFEF;text-align:right;white-space:nowrap}
.cpf-monthly-heatmap .cpf-monthly-heatmap-up{color:#25E07A}
.cpf-monthly-heatmap .cpf-monthly-heatmap-dn{color:#FF5C6C}
@container (max-width: 320px){.cpf-monthly-heatmap-c{font-size:6.2px;letter-spacing:-.06em}.cpf-monthly-heatmap-grid{grid-template-columns:19px repeat(12,minmax(0,1fr)) 25px}.cpf-monthly-heatmap-ft{grid-template-columns:repeat(2,1fr)}}
@media (prefers-reduced-motion: reduce){.cpf-monthly-heatmap-c{transition:none}}

