var P = 'cpf-monthly-heatmap';
var seed = 55118;
function rnd() { seed = seed + 0x6D2B79F5 | 0; var t = Math.imul(seed ^ seed >>> 15, 1 | seed); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; }
function gauss() { var u = 1 - rnd(), v = rnd(); return Math.sqrt(-2 * Math.log(u)) * Math.cos(6.283185307 * v); }
var MON = ['JAN','FEB','MAR','APR','MAY','JUN','JUL','AUG','SEP','OCT','NOV','DEC'];
var Y0 = 2018, SHOW0 = 2019, YN = 2026, LASTM = 7; /* last complete month: Aug 2026 */
/* index-level shocks in the benchmark (month key -> return) */
var SHOCK = { '2018-9': -0.071, '2018-11': -0.064, '2019-0': 0.079, '2019-4': -0.059, '2020-1': -0.081, '2020-2': -0.128, '2020-3': 0.109, '2020-10': 0.121, '2022-0': -0.049, '2022-2': 0.021, '2022-3': -0.083, '2022-5': -0.084, '2022-6': 0.071, '2022-8': -0.093, '2022-9': 0.059, '2023-9': -0.031, '2023-10': 0.091, '2025-2': -0.052, '2025-3': -0.041, '2025-4': 0.064 };
var F = [], B = [], KEY = [];
for (var y = Y0; y <= YN; y++) for (var mo = 0; mo < 12; mo++) {
  if (y === YN && mo > LASTM) break;
  var b = SHOCK[y + '-' + mo];
  if (b == null) b = 0.0105 + 0.026 * gauss();
  var f = 0.0024 + 0.84 * b + 0.0095 * gauss();
  B.push(b); F.push(f); KEY.push([y, mo]);
}
function at(y, mo) { var i = (y - Y0) * 12 + mo; return i < F.length ? i : -1; }
function comp(arr, a, z) { var v = 1; for (var i = a; i <= z; i++) v *= 1 + arr[i]; return v - 1; }
function r12(arr, i) { return i >= 11 ? comp(arr, i - 11, i) : null; }
function yr(arr, y) { var a = at(y, 0), z = y === YN ? at(y, LASTM) : at(y, 11); return comp(arr, a, z); }
function ytd(arr, i) { return comp(arr, i - KEY[i][1], i); }
var MODES = {
  m: { s: 0.06, dp: 1, lab: 'MONTHLY NET RETURN %', v: function (i) { return F[i]; }, y: function (y) { return yr(F, y); } },
  r: { s: 0.30, dp: 0, lab: 'TRAILING 12M RETURN %', v: function (i) { return r12(F, i); }, y: function (y) { return yr(F, y); } },
  x: { s: 0.03, dp: 1, lab: 'EXCESS vs BM, % PTS', v: function (i) { return F[i] - B[i]; }, y: function (y) { return yr(F, y) - yr(B, y); } }
};
var mode = 'm', sel = at(YN, LASTM), grid = root.querySelector('.' + P + '-grid');
function sg(v, dp) { var t = Math.abs(v * 100).toFixed(dp); return (+t === 0 ? '' : v > 0 ? '+' : '−') + t; }
function pc(v) { return sg(v, 2) + '%'; }
function bg(v, s) {
  var a = Math.min(Math.abs(v) / s, 1);
  var al = (0.1 + 0.72 * Math.pow(a, 0.8)).toFixed(3);
  return v >= 0 ? 'rgba(37,224,122,' + al + ')' : 'rgba(255,92,108,' + al + ')';
}
function build() {
  var md = MODES[mode], h = '<span class="' + P + '-h"></span>';
  MON.forEach(function (m) { h += '<span class="' + P + '-h">' + m.charAt(0) + m.slice(1, 3).toLowerCase() + '</span>'; });
  h += '<span class="' + P + '-h">' + (mode === 'x' ? 'YR XS' : 'YEAR') + '</span>';
  for (var y = YN; y >= SHOW0; y--) {
    h += '<span class="' + P + '-y">' + y + '</span>';
    for (var mo = 0; mo < 12; mo++) {
      var i = at(y, mo);
      if (i < 0) { h += '<span class="' + P + '-c ' + P + '-na">·</span>'; continue; }
      var v = md.v(i);
      h += '<span class="' + P + '-c' + (i === sel ? ' ' + P + '-sel' : '') + '" data-i="' + i + '" style="background:' + bg(v, md.s) + (Math.abs(v) / md.s > 0.55 ? ';color:#F5F8FF' : '') + '">' + sg(v, md.dp) + '</span>';
    }
    var yv = md.y(y), ys = mode === 'x' ? md.s * 2 : 0.3;
    h += '<span class="' + P + '-c ' + P + '-yr" title="' + (y === YN ? 'YTD' : 'Calendar year') + '" style="background:' + bg(yv, ys) + (Math.abs(yv) / ys > 0.55 ? ';color:#F5F8FF' : '') + '">' + sg(yv, 1) + (y === YN ? '*' : '') + '</span>';
  }
  grid.innerHTML = h;
  root.querySelector('.' + P + '-lgl').textContent = sg(-md.s, 0) + '%';
  root.querySelector('.' + P + '-lgr').textContent = sg(md.s, 0) + '%';
  root.querySelector('.' + P + '-mode').textContent = md.lab + ' · *YTD';
  [].forEach.call(root.querySelectorAll('.' + P + '-seg button'), function (bt) {
    var on = bt.getAttribute('data-m') === mode;
    bt.classList.toggle(P + '-on', on); bt.setAttribute('aria-checked', on ? 'true' : 'false');
  });
  detail();
}
function cls(v) { return P + '-' + (v >= 0 ? 'up' : 'dn'); }
function detail() {
  var k = KEY[sel], xs = F[sel] - B[sel], rr = r12(F, sel);
  root.querySelector('.' + P + '-det').innerHTML = '<b>' + MON[k[1]] + ' ' + k[0] + '</b>' +
    '<span>FUND <b class="' + cls(F[sel]) + '">' + pc(F[sel]) + '</b></span>' +
    '<span>BM <b class="' + cls(B[sel]) + '">' + pc(B[sel]) + '</b></span>' +
    '<span>XS <b class="' + cls(xs) + '">' + (xs >= 0 ? '+' : '−') + Math.abs(xs * 1e4).toFixed(0) + ' bps</b></span>' +
    '<span>YTD <b class="' + cls(ytd(F, sel)) + '">' + pc(ytd(F, sel)) + '</b></span>' +
    (rr == null ? '' : '<span>R12M <b class="' + cls(rr) + '">' + pc(rr) + '</b></span>');
}
/* footer: monthly stats over the displayed window */
(function () {
  var a = at(SHOW0, 0), z = F.length - 1, best = a, worst = a, pos = 0, su = 0, nu = 0, sd = 0, nd = 0, fu = 0, bu = 0, fdn = 0, bdn = 0, n = z - a + 1;
  for (var i = a; i <= z; i++) {
    if (F[i] > F[best]) best = i;
    if (F[i] < F[worst]) worst = i;
    if (F[i] > 0) { pos++; su += F[i]; nu++; } else { sd += F[i]; nd++; }
    if (B[i] > 0) { fu += F[i]; bu += B[i]; } else { fdn += F[i]; bdn += B[i]; }
  }
  function lab(i) { return MON[KEY[i][1]].slice(0, 3) + String(KEY[i][0]).slice(2); }
  var cells = [
    ['BEST MO', pc(F[best]) , 'up', lab(best)], ['WORST MO', pc(F[worst]), 'dn', lab(worst)],
    ['HIT RATE', (pos / n * 100).toFixed(1) + '%', '', pos + '/' + n], ['AVG UP MO', pc(su / nu), 'up', ''],
    ['AVG DN MO', pc(sd / nd), 'dn', ''], ['UP CAPTURE', (fu / bu * 100).toFixed(1) + '%', '', ''],
    ['DN CAPTURE', (fdn / bdn * 100).toFixed(1) + '%', '', ''], ['ANN RET', pc(Math.pow(1 + comp(F, a, z), 12 / n) - 1), '', 'BM ' + pc(Math.pow(1 + comp(B, a, z), 12 / n) - 1)]
  ];
  root.querySelector('.' + P + '-ft').innerHTML = cells.map(function (c) {
    return '<div><span>' + c[0] + (c[3] ? ' · ' + c[3] : '') + '</span><b' + (c[2] ? ' class="' + P + '-' + c[2] + '"' : '') + '>' + c[1] + '</b></div>';
  }).join('');
})();
function select(i) {
  if (i < 0 || i >= F.length || KEY[i][0] < SHOW0) return;
  var old = grid.querySelector('.' + P + '-sel'); if (old) old.classList.remove(P + '-sel');
  sel = i;
  var c = grid.querySelector('[data-i="' + i + '"]'); if (c) c.classList.add(P + '-sel');
  detail();
}
grid.addEventListener('click', function (ev) {
  var c = ev.target.closest('[data-i]'); if (c) { select(+c.getAttribute('data-i')); root.focus({ preventScroll: true }); }
});
root.querySelector('.' + P + '-seg').addEventListener('click', function (ev) {
  var bt = ev.target.closest('button'); if (!bt) return; mode = bt.getAttribute('data-m'); build();
});
root.addEventListener('keydown', function (ev) {
  var k = ev.key, y = KEY[sel][0], mo = KEY[sel][1], t = -1;
  if (k === 'ArrowLeft') t = sel - 1;
  else if (k === 'ArrowRight') t = sel + 1;
  else if (k === 'ArrowUp') t = at(y + 1, mo);
  else if (k === 'ArrowDown') t = y - 1 >= SHOW0 ? at(y - 1, mo) : -1;
  else if (k === 'Home') t = at(y, 0);
  else if (k === 'End') t = y === YN ? at(y, LASTM) : at(y, 11);
  else if (k === 'm' || k === 'r' || k === 'x') { mode = k; build(); ev.preventDefault(); return; }
  else return;
  ev.preventDefault();
  if (t >= 0) select(t);
});
build();

css:
.cpf-return-histogram{box-sizing:border-box;width:100%;max-width:400px;min-width:0;background:#0B0F17;border:1px solid #1C2432;border-radius:8px;padding:9px 10px 8px;color:#8B98B0;font:9px/1.35 ui-monospace,Menlo,Consolas,monospace;font-variant-numeric:tabular-nums;outline:none}
.cpf-return-histogram *{box-sizing:border-box}
.cpf-return-histogram:focus-visible{border-color:#3A5BA0;box-shadow:0 0 0 1px #3A5BA0}
.cpf-return-histogram-hd{display:flex;justify-content:space-between;align-items:flex-start;gap:6px;margin-bottom:6px}
.cpf-return-histogram-t{font:700 10px/1.2 system-ui,-apple-system,Segoe UI,sans-serif;color:#E4EBF7;letter-spacing:.05em;min-width:0}
.cpf-return-histogram-t b{display:block;font:500 7px/1.4 ui-monospace,Menlo,Consolas,monospace;color:#5B6883;letter-spacing:.06em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.cpf-return-histogram-segs{display:flex;gap:4px;flex:none}
.cpf-return-histogram-seg{display:flex;border:1px solid #243047;border-radius:3px;overflow:hidden}
.cpf-return-histogram-seg button{font:600 7.5px/1 ui-monospace,Menlo,Consolas,monospace;color:#6B7890;background:transparent;border:0;border-left:1px solid #243047;padding:4px 5px;cursor:pointer}
.cpf-return-histogram-seg button:first-child{border-left:0}
.cpf-return-histogram-seg button:hover{color:#C9D4E8}
.cpf-return-histogram-seg .cpf-return-histogram-on{background:#1B2A45;color:#E4EBF7}
.cpf-return-histogram-plot{position:relative;height:104px;border-bottom:1px solid #2A3650;cursor:crosshair;touch-action:none}
.cpf-return-histogram-svg{position:absolute;inset:0;width:100%;height:100%;display:block}
.cpf-return-histogram-zero{stroke:#243047;stroke-width:1;vector-effect:non-scaling-stroke}
.cpf-return-histogram-bars rect{fill:#3B5B8F;transition:fill .15s ease,opacity .15s ease}
.cpf-return-histogram-bars rect.cpf-return-histogram-tl{fill:#C9475A}
.cpf-return-histogram-bars rect.cpf-return-histogram-hi{fill:#8FB8FF}
.cpf-return-histogram-bars rect.cpf-return-histogram-tl.cpf-return-histogram-hi{fill:#FF8A96}
.cpf-return-histogram-bars rect.cpf-return-histogram-grow{animation:cpf-return-histogram-rise .6s cubic-bezier(.3,.7,.2,1) both;transform-origin:50% 100%;transform-box:fill-box}
.cpf-return-histogram-norm{fill:none;stroke:#F5B942;stroke-width:1.4;vector-effect:non-scaling-stroke}
.cpf-return-histogram-vh{stroke:#FF5C6C;stroke-width:1;stroke-dasharray:3 2;vector-effect:non-scaling-stroke}
.cpf-return-histogram-vn{stroke:#F5B942;stroke-width:1;stroke-dasharray:1 2;vector-effect:non-scaling-stroke}
.cpf-return-histogram-tag{position:absolute;font-size:6.5px;letter-spacing:.04em;padding:0 2px;background:rgba(11,15,23,.85);white-space:nowrap;pointer-events:none;transform:translateX(-100%)}
.cpf-return-histogram-th{top:12px;color:#FF7F8B}
.cpf-return-histogram-tn{top:22px;color:#F5B942}
.cpf-return-histogram-lg{position:absolute;right:1px;top:0;font-size:6.5px;letter-spacing:.05em;color:#6B7890;display:flex;align-items:center;gap:3px;pointer-events:none;background:rgba(11,15,23,.7)}
.cpf-return-histogram-lg i{display:inline-block;width:7px;height:5px;margin-left:3px}
.cpf-return-histogram-k1{background:#3B5B8F}
.cpf-return-histogram-k2{height:0;border-top:1.5px solid #F5B942}
.cpf-return-histogram-lg .cpf-return-histogram-k2{height:0}
.cpf-return-histogram-k3{background:#C9475A}
.cpf-return-histogram-ymax{position:absolute;left:1px;top:0;font-size:6.5px;color:#4B5772;pointer-events:none}
.cpf-return-histogram-xax{position:relative;height:11px;font-size:7px;color:#5B6883}
.cpf-return-histogram-xax span{position:absolute;top:1px;transform:translateX(-50%);white-space:nowrap}
.cpf-return-histogram-read{padding:4px 5px;margin:3px 0 6px;background:#0F1420;border:1px solid #1A2230;border-radius:3px;font-size:8.2px;min-height:19px;display:flex;flex-wrap:wrap;gap:1px 8px}
.cpf-return-histogram-read b{color:#E4EBF7;font-weight:600}
.cpf-return-histogram-st{display:grid;grid-template-columns:repeat(4,1fr);gap:1px;background:#1A2230;border:1px solid #1A2230;border-radius:3px;overflow:hidden}
.cpf-return-histogram-st div{background:#0B0F17;padding:3px 4px;min-width:0}
.cpf-return-histogram-st span{display:block;font-size:6.5px;letter-spacing:.08em;color:#4B5772;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.cpf-return-histogram-st b{display:block;font-size:9px;font-weight:600;color:#D6DFEF;text-align:right;white-space:nowrap}
.cpf-return-histogram .cpf-return-histogram-up{color:#25E07A}
.cpf-return-histogram .cpf-return-histogram-dn{color:#FF5C6C}
.cpf-return-histogram .cpf-return-histogram-am{color:#F5B942}
@keyframes cpf-return-histogram-rise{from{transform:scaleY(0)}to{transform:scaleY(1)}}
@media (prefers-reduced-motion: reduce){.cpf-return-histogram-bars rect{transition:none}.cpf-return-histogram-bars rect.cpf-return-histogram-grow{animation:none}}

