var P = 'cpf-return-histogram';
function q(s) { return root.querySelector('.' + P + '-' + s); }
var seed = 40427;
function rnd() { seed = seed + 0x6D2B79F5 | 0; var t = Math.imul(seed ^ seed >>> 15, 1 | seed); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; }
function gauss() { var u = 1 - rnd(), v = rnd(); return Math.sqrt(-2 * Math.log(u)) * Math.cos(6.283185307 * v); }
var NAV = 412.6e6, W = 300, H = 100;
/* 3y of daily returns: calm regime plus a fat, left-skewed stress component */
var D = [];
for (var i = 0; i < 756; i++) D.push(rnd() < 0.075 ? -0.0024 + 0.0178 * gauss() : 0.00062 + 0.0066 * gauss());
var Wk = [];
for (i = 0; i + 5 <= D.length; i += 5) { var c = 1; for (var j = 0; j < 5; j++) c *= 1 + D[i + j]; Wk.push(c - 1); }
var SETS = {
  d: { r: D, lo: -0.04, hi: 0.04, bw: 0.0025, lab: '3Y DAILY', h: '1D', tick: 0.01 },
  w: { r: Wk, lo: -0.08, hi: 0.08, bw: 0.005, lab: '3Y WEEKLY (5D, NON-OVERLAP)', h: '1W', tick: 0.02 }
};
var hz = 'd', cf = 95, hover = -1, S, plot = q('plot');
function erf(x) { var s = x < 0 ? -1 : 1; x = Math.abs(x); var t = 1 / (1 + 0.3275911 * x); var y = 1 - (((((1.061405429 * t - 1.453152027) * t) + 1.421413741) * t - 0.284496736) * t + 0.254829592) * t * Math.exp(-x * x); return s * y; }
function Phi(z) { return 0.5 * (1 + erf(z / Math.SQRT2)); }
function pc(v, dp) { var t = Math.abs(v * 100).toFixed(dp == null ? 2 : dp); return (+t === 0 ? '' : v > 0 ? '+' : '−') + t + '%'; }
function stats(r) {
  var n = r.length, m = 0, k;
  for (k = 0; k < n; k++) m += r[k];
  m /= n;
  var m2 = 0, m3 = 0, m4 = 0;
  for (k = 0; k < n; k++) { var e = r[k] - m; m2 += e * e; m3 += e * e * e; m4 += e * e * e * e; }
  var sd = Math.sqrt(m2 / (n - 1)), pv = m2 / n;
  var sk = (m3 / n) / Math.pow(pv, 1.5), ku = (m4 / n) / (pv * pv) - 3;
  var so = r.slice().sort(function (a, b) { return a - b; });
  return { n: n, m: m, sd: sd, sk: sk, ku: ku, so: so, jb: n / 6 * (sk * sk + ku * ku / 4) };
}
function quant(so, p) { var x = p * (so.length - 1), a = Math.floor(x), f = x - a; return so[a] + (so[Math.min(a + 1, so.length - 1)] - so[a]) * f; }
function build(anim) {
  S = SETS[hz];
  var st = stats(S.r), nb = Math.round((S.hi - S.lo) / S.bw), cnt = [], k;
  for (k = 0; k < nb; k++) cnt.push(0);
  st.so.forEach(function (v) { var b = Math.floor((v - S.lo) / S.bw); cnt[Math.max(0, Math.min(nb - 1, b))]++; });
  var z = cf === 95 ? 1.6449 : 2.3263, p = 1 - cf / 100;
  var vh = quant(st.so, p), vn = st.m - z * st.sd, es = 0, ne = 0;
  st.so.forEach(function (v) { if (v <= vh) { es += v; ne++; } });
  es /= ne;
  var exp = cnt.map(function (_, b) { var a = S.lo + b * S.bw; return st.n * (Phi((a + S.bw - st.m) / st.sd) - Phi((a - st.m) / st.sd)); });
  var ymax = Math.max.apply(null, cnt.concat(exp)) * 1.12;
  function X(v) { return (v - S.lo) / (S.hi - S.lo) * W; }
  function Yc(c) { return H - c / ymax * (H - 2); }
  var bw = W / nb, g = '';
  for (k = 0; k < nb; k++) {
    g += '<rect data-b="' + k + '" class="' + ((S.lo + k * S.bw) < vh ? P + '-tl' : '') + (anim ? ' ' + P + '-grow' : '') + '" x="' + (k * bw + 0.5).toFixed(2) + '" y="' + Yc(cnt[k]).toFixed(2) + '" width="' + (bw - 1).toFixed(2) + '" height="' + (H - Yc(cnt[k])).toFixed(2) + '" style="animation-delay:' + (k * 12) + 'ms"></rect>';
  }
  q('bars').innerHTML = g;
  var d = '';
  for (k = 0; k <= 150; k++) {
    var v = S.lo + (S.hi - S.lo) * k / 150, zz = (v - st.m) / st.sd;
    var c = st.n * S.bw * Math.exp(-0.5 * zz * zz) / (st.sd * Math.sqrt(2 * Math.PI));
    d += (k ? ' L' : 'M') + X(v).toFixed(2) + ',' + Yc(c).toFixed(2);
  }
  q('norm').setAttribute('d', d);
  var z0 = X(0); q('zero').setAttribute('x1', z0); q('zero').setAttribute('x2', z0);
  [['vh', vh], ['vn', vn]].forEach(function (a) { var l = q(a[0]), x = X(a[1]); l.setAttribute('x1', x); l.setAttribute('x2', x); });
  function tag(el, v, txt) {
    el.style.left = (X(v) / W * 100) + '%';
    el.textContent = txt + ' ▸'; el.style.transform = 'translateX(-100%)';
    var pw = plot.clientWidth;
    if (pw && X(v) / W * pw < el.offsetWidth + 2) { el.textContent = '◂ ' + txt; el.style.transform = 'none'; }
  }
  tag(q('th'), vh, 'HIST VaR' + cf + ' ' + pc(vh));
  tag(q('tn'), vn, 'NORM VaR' + cf + ' ' + pc(vn));
  q('ymax').textContent = 'n=' + st.n + ' · bin ' + (S.bw * 1e4) + 'bp';
  var xh = '';
  for (var t = S.lo; t <= S.hi + 1e-9; t += S.tick) xh += '<span style="left:' + (X(t) / W * 100).toFixed(2) + '%">' + (Math.abs(t) < 1e-9 ? '0' : pc(t, 0)) + '</span>';
  q('xax').innerHTML = xh;
  q('sub').textContent = 'KESTREL L/S EQUITY · ' + S.lab + ' · NAV $' + (NAV / 1e6).toFixed(1) + 'M';
  var cells = [
    ['MEAN ' + S.h, pc(st.m, 3), st.m >= 0 ? 'up' : 'dn'], ['STDEV ' + S.h, pc(st.sd, 3).replace('+', ''), ''],
    ['SKEW', (st.sk >= 0 ? '+' : '−') + Math.abs(st.sk).toFixed(2), st.sk < 0 ? 'dn' : 'up'], ['EX KURTOSIS', (st.ku >= 0 ? '+' : '−') + Math.abs(st.ku).toFixed(2), st.ku > 1 ? 'am' : ''],
    ['HIST VaR' + cf, pc(vh), 'dn'], ['NORM VaR' + cf, pc(vn), 'am'],
    ['ES / CVaR' + cf, pc(es), 'dn'], ['VaR $ ' + S.h, '−$' + (Math.abs(vh) * NAV / 1e6).toFixed(2) + 'M', 'dn']
  ];
  q('st').innerHTML = cells.map(function (c) { return '<div><span>' + c[0] + '</span><b' + (c[2] ? ' class="' + P + '-' + c[2] + '"' : '') + '>' + c[1] + '</b></div>'; }).join('');
  S.cnt = cnt; S.exp = exp; S.st = st; S.vh = vh; S.vn = vn; S.nb = nb;
  [].forEach.call(root.querySelectorAll('.' + P + '-seg'), function (sg) {
    var cur = sg.getAttribute('data-g') === 'h' ? hz : String(cf);
    [].forEach.call(sg.children, function (bt) { var on = bt.getAttribute('data-v') === cur; bt.classList.toggle(P + '-on', on); bt.setAttribute('aria-pressed', on ? 'true' : 'false'); });
  });
  if (hover >= nb) hover = nb - 1;
  read();
}
function read() {
  var el = q('read'), st = S.st;
  [].forEach.call(q('bars').children, function (r, k) { r.classList.toggle(P + '-hi', k === hover); });
  if (hover < 0) {
    var ratio = S.vh / S.vn;
    el.innerHTML = '<span>JARQUE-BERA <b>' + st.jb.toFixed(1) + '</b></span><span>' + (st.jb > 13.82 ? '<b class="' + P + '-dn">reject normal p&lt;0.001</b>' : st.jb > 5.99 ? '<b class="' + P + '-am">reject normal p&lt;0.05</b>' : '<b class="' + P + '-up">normal not rejected</b>') + '</span><span>HIST/NORM VaR <b class="' + P + '-' + (ratio > 1 ? 'dn' : 'up') + '">' + ratio.toFixed(2) + 'x</b></span>';
    return;
  }
  var a = S.lo + hover * S.bw, b = a + S.bw, o = S.cnt[hover], e = S.exp[hover], df = o - e;
  var lbl = hover === 0 ? '≤' + pc(b) : hover === S.nb - 1 ? '≥' + pc(a) : pc(a) + ' to ' + pc(b);
  el.innerHTML = '<b>' + lbl + '</b><span>OBS <b>' + o + '</b> (' + (o / st.n * 100).toFixed(1) + '%)</span><span>NORMAL <b>' + e.toFixed(1) + '</b></span><span>Δ <b class="' + P + '-' + (df >= 0 ? 'up' : 'dn') + '">' + (df >= 0 ? '+' : '−') + Math.abs(df).toFixed(1) + '</b></span>';
}
plot.addEventListener('pointermove', function (ev) {
  var rc = plot.getBoundingClientRect(); if (!rc.width) return;
  var b = Math.floor((ev.clientX - rc.left) / rc.width * S.nb);
  hover = Math.max(0, Math.min(S.nb - 1, b)); read();
});
plot.addEventListener('pointerleave', function () { hover = -1; read(); });
root.addEventListener('click', function (ev) {
  var bt = ev.target.closest('.' + P + '-seg button'); if (!bt) return;
  if (bt.parentNode.getAttribute('data-g') === 'h') hz = bt.getAttribute('data-v'); else cf = +bt.getAttribute('data-v');
  build(false);
});
root.addEventListener('keydown', function (ev) {
  var k = ev.key;
  if (k === 'ArrowLeft') hover = hover < 0 ? Math.floor(S.nb / 2) : Math.max(0, hover - 1);
  else if (k === 'ArrowRight') hover = hover < 0 ? Math.floor(S.nb / 2) : Math.min(S.nb - 1, hover + 1);
  else if (k === 'Escape') hover = -1;
  else if (k === 'd' || k === 'w') { hz = k; build(false); ev.preventDefault(); return; }
  else if (k === '5' || k === '9') { cf = k === '5' ? 95 : 99; build(false); ev.preventDefault(); return; }
  else return;
  ev.preventDefault(); read();
});
build(true);

