var P = 'cpf-risk-return-map';
function q(s) { return root.querySelector('.' + P + '-' + s); }
var RF = 0.043, XMAX = 0.65, YMIN = -0.20, YMAX = 0.65, W = 300, H = 150;
/* ticker, name, class, weight, 1Y return, 1Y vol, beta vs policy BM */
var HOLD = [
  ['GLD', 'SPDR Gold Shares', 'au', 0.150, 0.274, 0.163, 0.12],
  ['TLT', 'iShares 20+Y Treasury', 'du', 0.146, -0.024, 0.158, -0.14],
  ['MSFT', 'Microsoft Corp', 'eq', 0.104, 0.217, 0.223, 1.05],
  ['AAPL', 'Apple Inc', 'eq', 0.098, 0.124, 0.268, 1.12],
  ['AMZN', 'Amazon.com Inc', 'eq', 0.072, 0.249, 0.326, 1.28],
  ['NVDA', 'NVIDIA Corp', 'eq', 0.065, 0.582, 0.487, 1.92],
  ['PG', 'Procter & Gamble', 'eq', 0.063, 0.041, 0.172, 0.44],
  ['JPM', 'JPMorgan Chase', 'eq', 0.061, 0.313, 0.204, 1.04],
  ['LLY', 'Eli Lilly & Co', 'eq', 0.058, 0.381, 0.354, 0.58],
  ['XOM', 'Exxon Mobil', 'eq', 0.054, -0.038, 0.253, 0.71],
  ['KO', 'Coca-Cola Co', 'eq', 0.052, 0.098, 0.139, 0.51],
  ['UNH', 'UnitedHealth Group', 'eq', 0.046, -0.146, 0.318, 0.62],
  ['TSLA', 'Tesla Inc', 'eq', 0.031, 0.470, 0.618, 2.18]
];
var BM = { r: 0.112, v: 0.129, lab: 'POLICY BM 70/30' };
function rho(a, b) {
  if (a === b) return a === 'eq' ? 0.38 : 1;
  var k = [a, b].sort().join('');
  return { dueq: -0.12, aueq: 0.08, audu: 0.22 }[k];
}
var n = HOLD.length, i, j;
/* portfolio variance and marginal risk: (Sigma w)_i */
var mr = [], pv = 0, pr = 0, pb = 0, sw = 0;
for (i = 0; i < n; i++) {
  var s = 0;
  for (j = 0; j < n; j++) {
    var c = i === j ? 1 : rho(HOLD[i][2], HOLD[j][2]);
    s += c * HOLD[i][5] * HOLD[j][5] * HOLD[j][3];
  }
  mr.push(s); pv += HOLD[i][3] * s;
  pr += HOLD[i][3] * HOLD[i][4]; pb += HOLD[i][3] * HOLD[i][6]; sw += HOLD[i][3] * HOLD[i][5];
}
var pvol = Math.sqrt(pv);
var rc = HOLD.map(function (h, k) { return h[3] * mr[k] / pv; });
function sh(r, v) { return (r - RF) / v; }
function X(v) { return v / XMAX * 100; }
function Y(r) { return (YMAX - r) / (YMAX - YMIN) * 100; }
function pc(v, dp) { var t = Math.abs(v * 100).toFixed(dp == null ? 1 : dp); return (+t === 0 ? '' : v > 0 ? '+' : '−') + t + '%'; }
function sg(v, dp) { return (v >= 0 ? '+' : '−') + Math.abs(v).toFixed(dp); }
function tone(r, v) { var x = sh(r, v); return x < 0 ? 'r' : x < 1 ? 'a' : 'g'; }
/* grid, zero line and iso-Sharpe rays from (0, rf) */
var NS = 'http://www.w3.org/2000/svg', gg = q('grid'), iso = q('iso');
function ln(g, x1, y1, x2, y2, cl) { var l = document.createElementNS(NS, 'line'); l.setAttribute('x1', x1); l.setAttribute('y1', y1); l.setAttribute('x2', x2); l.setAttribute('y2', y2); if (cl) l.setAttribute('class', cl); g.appendChild(l); }
var yh = '', xh = '', t;
for (t = -0.2; t <= 0.6001; t += 0.2) { var yy = Y(t) / 100 * H; ln(gg, 0, yy, W, yy, Math.abs(t) < 1e-9 ? P + '-z' : ''); yh += '<span style="top:' + yy.toFixed(1) + 'px">' + (Math.abs(t) < 1e-9 ? '0%' : pc(t, 0)) + '</span>'; }
for (t = 0.1; t <= 0.6001; t += 0.1) { var xx = X(t) / 100 * W; ln(gg, xx, 0, xx, H); xh += '<span style="left:calc(24px + (100% - 24px) * ' + (X(t) / 100).toFixed(4) + ')">' + (t * 100).toFixed(0) + '%</span>'; }
q('yax').innerHTML = yh; q('xax').innerHTML = xh;
var il = '';
[0.5, 1, 1.5].forEach(function (s) {
  var v1 = XMAX, r1 = RF + s * v1;
  if (r1 > YMAX) { v1 = (YMAX - RF) / s; r1 = YMAX; }
  ln(iso, 0, Y(RF) / 100 * H, X(v1) / 100 * W, Y(r1) / 100 * H);
  var lx = X(Math.min(v1, XMAX * 0.97)), ly = Y(RF + s * Math.min(v1, XMAX * 0.97));
  il += '<span style="' + (v1 < XMAX ? 'right:auto;left:' + (lx - 2).toFixed(1) + '%;transform:translate(-100%,0);top:' + (ly + 1).toFixed(1) + '%' : 'top:' + ly.toFixed(1) + '%') + '">SR ' + s.toFixed(1) + '</span>';
});
q('isol').innerHTML = il;
var mode = 'w', sel = 0, pts = q('pts');
function size(k) { var v = mode === 'w' ? HOLD[k][3] : Math.max(rc[k], 0.004); return 4 + 26 * Math.sqrt(v); }
function draw() {
  var h = '';
  HOLD.forEach(function (x, k) {
    var d = size(k);
    h += '<span class="' + P + '-pt ' + P + '-' + tone(x[4], x[5]) + (k === sel ? ' ' + P + '-sel' : '') + '" data-k="' + k + '" style="left:' + X(x[5]) + '%;top:' + Y(x[4]) + '%;width:' + d.toFixed(1) + 'px;height:' + d.toFixed(1) + 'px;animation-delay:' + (k * 35) + 'ms"></span>';
  });
  h += '<span class="' + P + '-bm" style="left:' + X(BM.v) + '%;top:' + Y(BM.r) + '%"></span>';
  h += '<span class="' + P + '-pf" style="left:' + X(pvol) + '%;top:' + Y(pr) + '%"></span>';
  pts.innerHTML = h;
  labels();
}
/* greedy label placement: try right, left, above, below; skip a label that would collide */
function labels() {
  [].forEach.call(pts.querySelectorAll('.' + P + '-lb'), function (e) { e.remove(); });
  var pw = pts.clientWidth || 290, ph = pts.clientHeight || H, boxes = [], out = '';
  var items = HOLD.map(function (x, k) { return { k: k, t: x[0], x: X(x[5]) / 100 * pw, y: Y(x[4]) / 100 * ph, r: size(k) / 2 }; });
  items.push({ k: -1, t: 'PORT', x: X(pvol) / 100 * pw, y: Y(pr) / 100 * ph, r: 5 });
  items.push({ k: -2, t: 'BM', x: X(BM.v) / 100 * pw, y: Y(BM.r) / 100 * ph, r: 5 });
  items.forEach(function (it) { boxes.push([it.x - it.r, it.y - it.r, it.x + it.r, it.y + it.r]); });
  items.sort(function (a, b) { return (a.k === sel ? -9 : a.k < 0 ? -5 : 0) - (b.k === sel ? -9 : b.k < 0 ? -5 : 0); });
  items.forEach(function (it) {
    var w = it.t.length * 4.1 + 2, hh = 8, c = [
      [it.x + it.r + 2, it.y - hh / 2], [it.x - it.r - 2 - w, it.y - hh / 2],
      [it.x - w / 2, it.y - it.r - hh - 1], [it.x - w / 2, it.y + it.r + 1]];
    var pick1 = null, fall = null;
    for (var m = 0; m < c.length && !pick1; m++) {
      var bx = [c[m][0], c[m][1], c[m][0] + w, c[m][1] + hh];
      if (bx[0] < 1 || bx[2] > pw - 1 || bx[1] < 8 || bx[3] > ph - 1) continue;
      if (!fall) fall = bx;
      var hit = boxes.some(function (o) { return !(bx[2] <= o[0] || bx[0] >= o[2] || bx[3] <= o[1] || bx[1] >= o[3]); });
      if (!hit) pick1 = bx;
    }
    if (!pick1 && (it.k === sel || it.k < 0)) pick1 = fall;
    if (!pick1) return;
    boxes.push(pick1);
    out += '<span class="' + P + '-lb' + (it.k === sel ? ' ' + P + '-lsel' : '') + '" style="left:' + pick1[0].toFixed(1) + 'px;top:' + pick1[1].toFixed(1) + 'px' + (it.k === -1 ? ';color:#6EA8FF' : it.k === -2 ? ';color:#C9D4E8' : '') + '">' + it.t + '</span>';
  });
  pts.insertAdjacentHTML('beforeend', out);
}
function detail() {
  var x = HOLD[sel], s = sh(x[4], x[5]);
  var ctr = x[3] * x[4];
  q('det').innerHTML = '<div class="' + P + '-nm"><b>' + x[0] + ' <em>' + x[1] + '</em></b><em>' + (sel + 1) + '/' + n + ' · ' + ({ eq: 'EQUITY', du: 'DURATION', au: 'GOLD' })[x[2]] + '</em></div>' +
    '<div><span>WEIGHT</span><i>' + (x[3] * 100).toFixed(1) + '%</i></div>' +
    '<div><span>1Y RETURN</span><i class="' + P + '-' + (x[4] >= 0 ? 'up' : 'dn') + '">' + pc(x[4]) + '</i></div>' +
    '<div><span>1Y VOL</span><i>' + (x[5] * 100).toFixed(1) + '%</i></div>' +
    '<div><span>SHARPE</span><i class="' + P + '-' + (s < 0 ? 'dn' : s < 1 ? 'am' : 'up') + '">' + sg(s, 2) + '</i></div>' +
    '<div><span>BETA</span><i>' + x[6].toFixed(2) + '</i></div>' +
    '<div><span>CTR RETURN</span><i class="' + P + '-' + (ctr >= 0 ? 'up' : 'dn') + '">' + (ctr >= 0 ? '+' : '−') + Math.abs(ctr * 1e4).toFixed(0) + 'bp</i></div>' +
    '<div><span>% OF RISK</span><i>' + (rc[sel] * 100).toFixed(1) + '%</i></div>' +
    '<div><span>RISK/WT</span><i class="' + P + '-' + (rc[sel] / x[3] > 1 ? 'am' : 'up') + '">' + (rc[sel] / x[3]).toFixed(2) + 'x</i></div>';
}
function summary() {
  var ps = sh(pr, pvol), bs = sh(BM.r, BM.v);
  q('sum').innerHTML = '<span class="' + P + '-sh"></span><span class="' + P + '-sh">RETURN</span><span class="' + P + '-sh">VOL</span><span class="' + P + '-sh">SHARPE</span><span class="' + P + '-sh">BETA</span>' +
    '<span class="' + P + '-rl"><b style="color:#6EA8FF">◆</b> PORT</span><span class="' + P + '-up">' + pc(pr, 2) + '</span><span>' + (pvol * 100).toFixed(2) + '%</span><span>' + sg(ps, 2) + '</span><span>' + pb.toFixed(2) + '</span>' +
    '<span class="' + P + '-rl">□ BM 70/30</span><span class="' + P + '-up">' + pc(BM.r, 2) + '</span><span>' + (BM.v * 100).toFixed(2) + '%</span><span>' + sg(bs, 2) + '</span><span>1.00</span>' +
    '<span class="' + P + '-rl">DIV RATIO</span><span>' + (sw / pvol).toFixed(2) + 'x</span><span class="' + P + '-sh" style="grid-column:span 3;text-align:right">Σwσ ' + (sw * 100).toFixed(2) + '% vs σp ' + (pvol * 100).toFixed(2) + '%</span>';
}
function pick(k) {
  sel = (k + n) % n;
  [].forEach.call(pts.querySelectorAll('.' + P + '-pt'), function (e) { e.classList.toggle(P + '-sel', +e.getAttribute('data-k') === sel); });
  labels(); detail();
}
pts.addEventListener('click', function (ev) { var e = ev.target.closest('.' + P + '-pt'); if (e) pick(+e.getAttribute('data-k')); });
root.querySelector('.' + P + '-seg').addEventListener('click', function (ev) {
  var b = ev.target.closest('button'); if (!b) return; setMode(b.getAttribute('data-s'));
});
function setMode(m) {
  mode = m;
  [].forEach.call(root.querySelectorAll('.' + P + '-seg button'), function (b) { var on = b.getAttribute('data-s') === mode; b.classList.toggle(P + '-on', on); b.setAttribute('aria-pressed', on ? 'true' : 'false'); });
  [].forEach.call(pts.querySelectorAll('.' + P + '-pt'), function (e) { var d = size(+e.getAttribute('data-k')).toFixed(1) + 'px'; e.style.width = d; e.style.height = d; e.style.animation = 'none'; });
  labels();
}
root.addEventListener('keydown', function (ev) {
  var k = ev.key;
  if (k === 'ArrowRight' || k === 'ArrowDown') pick(sel + 1);
  else if (k === 'ArrowLeft' || k === 'ArrowUp') pick(sel - 1);
  else if (k === 's' || k === 'S') setMode(mode === 'w' ? 'r' : 'w');
  else return;
  ev.preventDefault();
});
if (typeof ResizeObserver === 'function') { var lastW = 0; new ResizeObserver(function () { var w = pts.clientWidth; if (w && w !== lastW) { lastW = w; labels(); } }).observe(pts); }
draw(); detail(); summary();

