var P = 'cpf-attribution-waterfall';
function q(s) { return root.querySelector('.' + P + '-' + s); }
/* GICS L1 sector, weight port %, weight BM %, return port %, return BM % (YTD). Unheld sector: rP set to rB. */
var SEC = [
  ['Info Tech', 'IT', 36.0, 33.3, 22.4, 18.6], ['Financials', 'FIN', 11.2, 13.4, 10.8, 12.1],
  ['Health Care', 'HC', 12.5, 9.8, 7.9, 4.2], ['Cons Discr', 'CD', 8.1, 10.6, 3.1, 6.5],
  ['Comm Svcs', 'COM', 10.4, 9.6, 24.0, 21.3], ['Industrials', 'IND', 9.9, 8.4, 13.2, 11.8],
  ['Cons Staples', 'CS', 3.2, 5.4, 4.1, 3.4], ['Energy', 'EN', 1.5, 3.1, -1.2, -2.7],
  ['Utilities', 'UT', 1.8, 2.4, 12.6, 14.9], ['Real Estate', 'RE', 0.0, 2.1, 2.8, 2.8],
  ['Materials', 'MAT', 2.1, 1.9, 6.8, 5.1], ['Cash', 'CASH', 3.3, 0.0, 3.2, 3.2]
];
var FEES = 0.55; /* mgmt fee accrual + trading costs, % YTD */
var Rb = 0, Rp = 0, TA = 0, TS = 0, TI = 0;
SEC.forEach(function (s) { Rb += s[3] * s[5] / 100; Rp += s[2] * s[4] / 100; });
var AT = SEC.map(function (s) {
  var dw = (s[2] - s[3]) / 100;
  var a = dw * (s[5] - Rb), se = s[3] / 100 * (s[4] - s[5]), it = dw * (s[4] - s[5]);
  TA += a; TS += se; TI += it;
  return { n: s[0], k: s[1], wp: s[2], wb: s[3], rp: s[4], rb: s[5], a: a, s: se, i: it, t: a + se + it };
});
var NET = Rp - FEES, mode = 'e', sel = 0, rows = [];
function bp(v) { var t = Math.round(v * 100); return (t > 0 ? '+' : t < 0 ? '−' : '') + Math.abs(t) + 'bp'; }
function pc(v) { return (v > 0 ? '+' : v < 0 ? '−' : '') + Math.abs(v).toFixed(2) + '%'; }
function cl(v) { return P + '-' + (v >= 0 ? 'up' : 'dn'); }
function model() {
  rows = [{ lb: 'BENCHMARK', tot: 1, v: Rb, kind: 'bm' }];
  if (mode === 'e') {
    rows.push({ lb: 'Allocation', v: TA, kind: 'fx', f: 'A' });
    rows.push({ lb: 'Selection', v: TS, kind: 'fx', f: 'S' });
    rows.push({ lb: 'Interaction', v: TI, kind: 'fx', f: 'I' });
  } else {
    AT.slice().sort(function (a, b) { return b.t - a.t; }).forEach(function (s) { rows.push({ lb: s.n, v: s.t, kind: 'sec', s: s }); });
  }
  rows.push({ lb: 'GROSS PORT', tot: 1, v: Rp, kind: 'gross' });
  rows.push({ lb: 'Fees & costs', v: -FEES, kind: 'fee' });
  rows.push({ lb: 'NET PORT', tot: 1, v: NET, kind: 'net' });
  var c = 0;
  rows.forEach(function (r) { if (r.tot) { r.a = 0; r.b = r.v; c = r.v; } else { r.a = c; r.b = c + r.v; c = r.b; } });
}
function render() {
  model();
  var lo = Infinity, hi = -Infinity;
  rows.forEach(function (r) { if (!r.tot) { lo = Math.min(lo, r.a, r.b); hi = Math.max(hi, r.a, r.b); } else { lo = Math.min(lo, r.v); hi = Math.max(hi, r.v); } });
  lo = Math.floor(lo - 0.4); hi = Math.ceil(hi + 0.4);
  var step = hi - lo > 6 ? 2 : 1;
  function X(v) { return (Math.max(v, lo) - lo) / (hi - lo) * 100; }
  var ax = '', gl = '';
  for (var t = lo; t <= hi; t += step) { ax += '<span style="left:' + X(t).toFixed(2) + '%">' + t + '%</span>'; gl += '<i style="left:' + X(t).toFixed(2) + '%"></i>'; }
  q('ax').innerHTML = ax;
  var h = '<div class="' + P + '-gl">' + gl + '</div>';
  rows.forEach(function (r, k) {
    var x0, x1, bc;
    if (r.tot) { x0 = 0; x1 = X(r.v); bc = r.kind === 'net' ? 'nbar' : 'tbar'; }
    else { x0 = X(Math.min(r.a, r.b)); x1 = X(Math.max(r.a, r.b)); bc = r.v >= 0 ? 'pos' : 'neg'; }
    var nxt = rows[k + 1], cn = nxt ? '<i class="' + P + '-cn" style="left:' + X(r.tot ? r.v : r.b).toFixed(2) + '%"></i>' : '';
    h += '<div class="' + P + '-row' + (r.tot ? ' ' + P + '-tot' : '') + (k === sel ? ' ' + P + '-sel' : '') + '" role="option" aria-selected="' + (k === sel) + '" data-k="' + k + '">' +
      '<span class="' + P + '-lb">' + r.lb + '</span><span class="' + P + '-trk">' +
      (r.tot ? '<i class="' + P + '-brk"></i>' : '') +
      '<i class="' + P + '-bar ' + P + '-' + bc + '" style="left:' + x0.toFixed(2) + '%;width:' + Math.max(x1 - x0, 0.4).toFixed(2) + '%;animation-delay:' + (k * 40) + 'ms' + (!r.tot && r.v < 0 ? ';transform-origin:right center' : '') + '"></i>' + cn +
      '</span><span class="' + P + '-v' + (r.tot ? '' : ' ' + cl(r.v)) + '">' + (r.tot ? pc(r.v) : bp(r.v)) + '</span></div>';
  });
  q('rows').innerHTML = h;
  [].forEach.call(root.querySelectorAll('.' + P + '-seg button'), function (b) { var on = b.getAttribute('data-v') === mode; b.classList.toggle(P + '-on', on); b.setAttribute('aria-pressed', on ? 'true' : 'false'); });
  q('chk').innerHTML = 'BM <b>' + pc(Rb) + '</b> + ALLOC <b>' + bp(TA) + '</b> + SEL <b>' + bp(TS) + '</b> + INT <b>' + bp(TI) + '</b> = GROSS <b>' + pc(Rp) + '</b> − FEES <b>' + FEES.toFixed(2) + '%</b> = NET <b>' + pc(NET) + '</b> <b class="' + P + '-ok">✓ ' + (Math.abs(Rb + TA + TS + TI - Rp) < 1e-9 ? 'reconciled' : 'residual') + '</b>';
  detail();
}
function top(f) { var b = AT.slice().sort(function (x, y) { return y[f] - x[f]; }); return [b[0], b[b.length - 1]]; }
function detail() {
  var r = rows[sel], h = '';
  if (r.kind === 'sec') {
    var s = r.s;
    h = '<b>' + s.n.toUpperCase() + '</b><span>wP <b>' + s.wp.toFixed(1) + '%</b> wB <b>' + s.wb.toFixed(1) + '%</b> ACT <b class="' + cl(s.wp - s.wb) + '">' + (s.wp - s.wb >= 0 ? '+' : '−') + Math.abs(s.wp - s.wb).toFixed(1) + '</b></span>' +
      '<span>rP <b>' + (s.wp === 0 ? 'n/h' : pc(s.rp)) + '</b> rB <b>' + pc(s.rb) + '</b></span>' +
      '<span>A <b class="' + cl(s.a) + '">' + bp(s.a) + '</b> S <b class="' + cl(s.s) + '">' + bp(s.s) + '</b> I <b class="' + cl(s.i) + '">' + bp(s.i) + '</b> = <b class="' + cl(s.t) + '">' + bp(s.t) + '</b></span>' +
      (s.wp === 0 ? '<em>Not held: selection and interaction are zero, the underweight shows up only as allocation.</em>' : '');
  } else if (r.kind === 'fx') {
    var f = r.f === 'A' ? 'a' : r.f === 'S' ? 's' : 'i', tb = top(f);
    var def = { A: 'Σ (wP−wB)(rB,i−RB): sector over/underweights', S: 'Σ wB (rP,i−rB,i): stock picking inside each sector', I: 'Σ (wP−wB)(rP,i−rB,i): overweighting where selection worked' }[r.f];
    h = '<b>' + r.lb.toUpperCase() + ' <span class="' + cl(r.v) + '">' + bp(r.v) + '</span></b><span>BEST <b>' + tb[0].k + ' ' + bp(tb[0][f]) + '</b></span><span>WORST <b>' + tb[1].k + ' ' + bp(tb[1][f]) + '</b></span><em>' + def + '</em>';
  } else if (r.kind === 'fee') {
    h = '<b>FEES &amp; COSTS <span class="' + P + '-dn">' + bp(r.v) + '</span></b><span>MGMT 0.70% p.a. × 266/365 <b>−51bp</b></span><span>TRADING <b>−4bp</b></span><em>Gross to net: attribution effects are measured before fees.</em>';
  } else {
    var ex = r.v - Rb;
    h = '<b>' + r.lb + ' <span class="' + cl(r.v) + '">' + pc(r.v) + '</span></b>' + (r.kind === 'bm' ? '<span>Σ wB·rB over ' + SEC.length + ' sleeves</span><em>Policy benchmark, total return, USD.</em>' : '<span>vs BM <b class="' + cl(ex) + '">' + bp(ex) + '</b></span><em>' + (r.kind === 'net' ? 'Net of the ' + FEES.toFixed(2) + '% fee and cost drag.' : 'Sum of allocation, selection and interaction on top of the benchmark.') + '</em>');
  }
  q('det').innerHTML = h;
}
function pick(k) {
  sel = Math.max(0, Math.min(rows.length - 1, k));
  [].forEach.call(q('rows').querySelectorAll('.' + P + '-row'), function (e, j) { e.classList.toggle(P + '-sel', j === sel); e.setAttribute('aria-selected', j === sel ? 'true' : 'false'); });
  detail();
}
q('rows').addEventListener('click', function (ev) { var e = ev.target.closest('.' + P + '-row'); if (e) pick(+e.getAttribute('data-k')); });
root.querySelector('.' + P + '-seg').addEventListener('click', function (ev) { var b = ev.target.closest('button'); if (!b) return; mode = b.getAttribute('data-v'); sel = Math.min(sel, mode === 'e' ? 6 : 15); render(); });
root.addEventListener('keydown', function (ev) {
  var k = ev.key;
  if (k === 'ArrowDown') pick(sel + 1);
  else if (k === 'ArrowUp') pick(sel - 1);
  else if (k === 'Home') pick(0);
  else if (k === 'End') pick(rows.length - 1);
  else if (k === 'e' || k === 's') { mode = k; sel = Math.min(sel, mode === 'e' ? 6 : 15); render(); }
  else return;
  ev.preventDefault();
});
render();

