var P = 'cpf-relative-cumulative';
function q(s) { return root.querySelector('.' + P + '-' + s); }
var seed = 8080;
function rnd() { seed = seed + 0x6D2B79F5 | 0; var t = Math.imul(seed ^ seed >>> 15, 1 | seed); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; }
function gauss() { var u = 1 - rnd(), v = rnd(); return Math.sqrt(-2 * Math.log(u)) * Math.cos(6.283185307 * v); }
var MON = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
var N = 1261, W = 300, H = 96, BH = 40;
var dates = [], d = new Date(Date.UTC(2026, 8, 23));
while (dates.length < N) { var wd = d.getUTCDay(); if (wd !== 0 && wd !== 6) dates.push(new Date(d.getTime())); d.setUTCDate(d.getUTCDate() - 1); }
dates.reverse();
/* benchmark with a drawdown year, fund = beta 0.91 plus a slowly cycling alpha */
var rf = [0], rb = [0], F = [1], B = [1];
for (var i = 1; i < N; i++) {
  var mb = 0.00062;
  if (i > 260 && i < 460) mb = -0.0008;
  if (i > 1080 && i < 1125) mb = -0.0012;
  var b = mb + 0.0102 * gauss();
  var al = 0.00011 + 0.00016 * Math.sin(i / 150);
  var f = al + 0.91 * b + 0.0031 * gauss();
  rb.push(b); rf.push(f); F.push(F[i - 1] * (1 + f)); B.push(B[i - 1] * (1 + b));
}
var ytd0 = 0;
for (i = N - 1; i > 0; i--) if (dates[i - 1].getUTCFullYear() < dates[N - 1].getUTCFullYear()) { ytd0 = i - 1; break; }
var PER = { ytd: ytd0, '1y': N - 1 - 252, '3y': N - 1 - 756, '5y': 0 };
var per = '1y', s0, idx = N - 1, lo, hi, rlo, rhi;
function fd(t) { var x = dates[t]; return ('0' + x.getUTCDate()).slice(-2) + ' ' + MON[x.getUTCMonth()] + ' ' + String(x.getUTCFullYear()).slice(2); }
function pc(v, dp) { var t = Math.abs(v * 100).toFixed(dp == null ? 2 : dp); return (+t === 0 ? '' : v > 0 ? '+' : '−') + t + '%'; }
function cf(t) { return F[t] / F[s0] - 1; }
function cb(t) { return B[t] / B[s0] - 1; }
function rel(t) { return (F[t] / F[s0]) / (B[t] / B[s0]) - 1; }
function X(t) { return (t - s0) / (N - 1 - s0) * W; }
function Y(v) { return 3 + (hi - v) / (hi - lo) * (H - 6); }
function Z(v) { return 2 + (rhi - v) / (rhi - rlo) * (BH - 4); }
function nice(span) { var c = [0.01, 0.02, 0.05, 0.1, 0.2, 0.25, 0.5]; for (var k = 0; k < c.length; k++) if (span / c[k] <= 4.5) return c[k]; return 1; }
var NS = 'http://www.w3.org/2000/svg';
function build() {
  s0 = PER[per];
  lo = 0; hi = 0; rlo = 0; rhi = 0;
  var t;
  for (t = s0; t < N; t++) { lo = Math.min(lo, cf(t), cb(t)); hi = Math.max(hi, cf(t), cb(t)); rlo = Math.min(rlo, rel(t)); rhi = Math.max(rhi, rel(t)); }
  var pd = (hi - lo) * 0.06; lo -= pd; hi += pd;
  var rp = Math.max(rhi - rlo, 0.004) * 0.12; rlo -= rp; rhi += rp;
  var fp = '', bp = '', ln = '', pos = '', neg = '', gapB = '', z0 = Z(0).toFixed(2);
  for (t = s0; t < N; t++) {
    var x = X(t).toFixed(2), c = t === s0 ? 'M' : ' L', r = rel(t);
    fp += c + x + ',' + Y(cf(t)).toFixed(2);
    bp += c + x + ',' + Y(cb(t)).toFixed(2);
    ln += c + x + ',' + Z(r).toFixed(2);
