  var zl = q('zl'); zl.setAttribute('y1', z0); zl.setAttribute('y2', z0);
  var g = q('grid'); g.innerHTML = '';
  var st = nice(hi - lo), ya = '';
  for (var v = Math.ceil(lo / st) * st; v <= hi; v += st) {
    var yy = Y(v), l = document.createElementNS(NS, 'line');
    l.setAttribute('x1', 0); l.setAttribute('x2', W); l.setAttribute('y1', yy); l.setAttribute('y2', yy);
    if (Math.abs(v) < 1e-9) l.setAttribute('class', P + '-z');
    g.appendChild(l);
    ya += '<span style="top:' + (yy / H * 100).toFixed(2) + '%">' + (Math.abs(v) < 1e-9 ? '0%' : pc(v, 0)) + '</span>';
  }
