  q('yb').innerHTML = '<span style="top:' + (Z(rhi - (rhi - rlo) * 0.1) / BH * 100).toFixed(1) + '%">' + pc(rhi - (rhi - rlo) * 0.1, 1) + '</span><span style="top:' + (Z(0) / BH * 100).toFixed(1) + '%">0%</span><span style="top:' + (Z(rlo + (rhi - rlo) * 0.1) / BH * 100).toFixed(1) + '%">' + pc(rlo + (rhi - rlo) * 0.1, 1) + '</span>';
