  var xh = '', span = N - 1 - s0, last = -1;
  for (t = s0 + 1; t < N; t++) {
    var dt = dates[t], pv = dates[t - 1];
    var brk = span > 300 ? dt.getUTCFullYear() !== pv.getUTCFullYear() : (dt.getUTCMonth() !== pv.getUTCMonth() && dt.getUTCMonth() % (span > 200 ? 3 : 2) === 0);
    if (brk && X(t) - last > 28 && X(t) < W - 10) { last = X(t); xh += '<span style="left:' + (X(t) / W * 100).toFixed(2) + '%">' + (span > 300 ? dt.getUTCFullYear() : MON[dt.getUTCMonth()] + ' ' + String(dt.getUTCFullYear()).slice(2)) + '</span>'; }
  }
