  q('read').innerHTML = '<b>' + fd(idx) + '</b><span>FUND ' + b(cf(idx)) + '</span><span>BM ' + b(cb(idx)) + '</span><span>REL ' + b(r) + '</span><span>ARITH <b class="' + P + '-' + (a >= 0 ? 'up' : 'dn') + '">' + (a >= 0 ? '+' : '−') + Math.abs(a * 1e4).toFixed(0) + 'bp</b></span>';
