root.querySelector('.' + P + '-seg').addEventListener('click', function (ev) { var bt = ev.target.closest('button'); if (!bt) return; per = bt.getAttribute('data-p'); build(); });
var plots = q('plots');
function fromPointer(ev) {
  var rc = q('top').getBoundingClientRect(); if (!rc.width) return;
  var f = Math.max(0, Math.min(1, (ev.clientX - rc.left) / rc.width));
