.cpf-rolling-sharpe{box-sizing:border-box;width:100%;max-width:400px;min-width:0;background:#0B0F17;border:1px solid #1C2432;border-radius:8px;padding:9px 10px 8px;color:#8B98B0;font:9px/1.35 ui-monospace,Menlo,Consolas,monospace;font-variant-numeric:tabular-nums;outline:none}
.cpf-rolling-sharpe *{box-sizing:border-box}
.cpf-rolling-sharpe:focus-visible{border-color:#3A5BA0;box-shadow:0 0 0 1px #3A5BA0}
.cpf-rolling-sharpe-hd{display:flex;justify-content:space-between;align-items:flex-start;gap:6px;margin-bottom:6px}
.cpf-rolling-sharpe-t{font:700 10px/1.2 system-ui,-apple-system,Segoe UI,sans-serif;color:#E4EBF7;letter-spacing:.05em;min-width:0}
.cpf-rolling-sharpe-t b{display:block;font:500 7px/1.4 ui-monospace,Menlo,Consolas,monospace;color:#5B6883;letter-spacing:.06em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.cpf-rolling-sharpe-seg{display:flex;border:1px solid #243047;border-radius:3px;overflow:hidden;flex:none}
.cpf-rolling-sharpe-seg button{font:600 7.5px/1 ui-monospace,Menlo,Consolas,monospace;color:#6B7890;background:transparent;border:0;border-left:1px solid #243047;padding:4px 6px;cursor:pointer}
.cpf-rolling-sharpe-seg button:first-child{border-left:0}
.cpf-rolling-sharpe-seg button:hover{color:#C9D4E8}
.cpf-rolling-sharpe-seg .cpf-rolling-sharpe-on{background:#1B2A45;color:#E4EBF7}
.cpf-rolling-sharpe-kpi{display:grid;grid-template-columns:repeat(6,1fr);border:1px solid #1A2230;border-radius:4px;margin-bottom:6px}
.cpf-rolling-sharpe-kpi div{padding:3px 4px;border-left:1px solid #1A2230;min-width:0}
.cpf-rolling-sharpe-kpi div:first-child{border-left:0}
.cpf-rolling-sharpe-kpi span{display:block;font-size:6.5px;letter-spacing:.07em;color:#4B5772;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.cpf-rolling-sharpe-kpi b{display:block;font-size:9.2px;font-weight:600;color:#D6DFEF;text-align:right;white-space:nowrap}
.cpf-rolling-sharpe-plots{position:relative;padding-left:22px;cursor:crosshair;touch-action:none}
.cpf-rolling-sharpe-plot{position:relative;height:110px;border-left:1px solid #2A3650}
.cpf-rolling-sharpe-svg{position:absolute;inset:0;width:100%;height:100%;display:block;overflow:visible;animation:cpf-rolling-sharpe-wipe .8s cubic-bezier(.3,.7,.2,1) both}
.cpf-rolling-sharpe-grid line{stroke:#151C28;stroke-width:1;vector-effect:non-scaling-stroke}
.cpf-rolling-sharpe-grid line.cpf-rolling-sharpe-z{stroke:#3A4866;stroke-width:1}
.cpf-rolling-sharpe-grid line.cpf-rolling-sharpe-g1{stroke:#1F3A2C;stroke-dasharray:3 3}
.cpf-rolling-sharpe-grid line.cpf-rolling-sharpe-g2{stroke:#1F3A2C;stroke-dasharray:1 3}
.cpf-rolling-sharpe-fp{fill:rgba(110,168,255,.13)}
.cpf-rolling-sharpe-fn{fill:rgba(255,92,108,.30)}
.cpf-rolling-sharpe-ln{fill:none;stroke:#6EA8FF;stroke-width:1.4;vector-effect:non-scaling-stroke;stroke-linejoin:round}
.cpf-rolling-sharpe-full{stroke:#F5B942;stroke-width:1;stroke-dasharray:4 3;vector-effect:non-scaling-stroke;opacity:.85}
.cpf-rolling-sharpe-cx{stroke:#C9D4E8;stroke-width:1;stroke-dasharray:2 2;vector-effect:non-scaling-stroke;opacity:.65}
.cpf-rolling-sharpe-dot{position:absolute;width:7px;height:7px;margin:-3.5px 0 0 -3.5px;border-radius:50%;background:#6EA8FF;border:1.5px solid #0B0F17;box-shadow:0 0 0 1px #6EA8FF;pointer-events:none;z-index:2}
.cpf-rolling-sharpe-ya{position:absolute;top:0;bottom:0;left:-22px;width:20px}
.cpf-rolling-sharpe-ya span{position:absolute;right:0;font-size:6.8px;color:#5B6883;transform:translateY(-50%)}
.cpf-rolling-sharpe-fl{position:absolute;right:2px;font-size:6.5px;color:#F5B942;background:rgba(11,15,23,.8);padding:0 2px;transform:translateY(-110%);pointer-events:none}
.cpf-rolling-sharpe-rib{display:block;width:100%;height:6px;margin-top:3px;border-radius:1px}
.cpf-rolling-sharpe-rib rect.cpf-rolling-sharpe-c0,.cpf-rolling-sharpe-b0{fill:#FF5C6C;background:#FF5C6C}
.cpf-rolling-sharpe-rib rect.cpf-rolling-sharpe-c1,.cpf-rolling-sharpe-b1{fill:#8A6A2A;background:#8A6A2A}
.cpf-rolling-sharpe-rib rect.cpf-rolling-sharpe-c2,.cpf-rolling-sharpe-b2{fill:#1E9E5C;background:#1E9E5C}
.cpf-rolling-sharpe-rib rect.cpf-rolling-sharpe-c3,.cpf-rolling-sharpe-b3{fill:#3DF295;background:#3DF295}
.cpf-rolling-sharpe-xax{position:relative;height:11px;font-size:7px;color:#5B6883}
.cpf-rolling-sharpe-xax span{position:absolute;top:1px;transform:translateX(-50%);white-space:nowrap}
.cpf-rolling-sharpe-key{display:flex;align-items:center;gap:7px;font-size:6.8px;color:#6B7890;margin:2px 0 4px}
.cpf-rolling-sharpe-key i{display:inline-block;width:8px;height:5px;margin-right:2px;border-radius:1px;vertical-align:0}
.cpf-rolling-sharpe-tm{font-style:normal;margin-left:auto;white-space:nowrap}
.cpf-rolling-sharpe-read{display:flex;flex-wrap:wrap;gap:1px 8px;padding:4px 5px;background:#0F1420;border:1px solid #1A2230;border-radius:3px;font-size:8.2px;min-height:19px}
.cpf-rolling-sharpe-read b{color:#E4EBF7;font-weight:600}
.cpf-rolling-sharpe .cpf-rolling-sharpe-up{color:#25E07A}
.cpf-rolling-sharpe .cpf-rolling-sharpe-dn{color:#FF5C6C}
.cpf-rolling-sharpe .cpf-rolling-sharpe-am{color:#F5B942}
@keyframes cpf-rolling-sharpe-wipe{from{clip-path:inset(0 100% 0 0)}to{clip-path:inset(0 0 0 0)}}
@media (prefers-reduced-motion: reduce){.cpf-rolling-sharpe-svg{animation:none}}

