var P = 'cpf-rolling-sharpe';
function q(s) { return root.querySelector('.' + P + '-' + s); }
var seed = 1001;
function rnd() { seed = seed + 0x6D2B79F5 | 0; var t = Math.imul(seed ^ seed >>> 15, 1 | seed); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; }
function gauss() { var u = 1 - rnd(), v = rnd(); return Math.sqrt(-2 * Math.log(u)) * Math.cos(6.283185307 * v); }
var MON = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
var RF = 0.0425, RFD = RF / 252, N = 1260, S0 = 252, W = 300, H = 110, YMIN = -3, YMAX = 4;
var dates = [], d = new Date(Date.UTC(2026, 8, 23));
while (dates.length < N) { var wd = d.getUTCDay(); if (wd !== 0 && wd !== 6) dates.push(new Date(d.getTime())); d.setUTCDate(d.getUTCDate() - 1); }
dates.reverse();
/* daily net returns with drifting regimes: strong, choppy, a crowded unwind, recovery */
var R = [];
for (var i = 0; i < N; i++) {
  var mu = 0.00072 + 0.00032 * Math.sin(i / 95) + 0.00012 * Math.sin(i / 23);
  if (i > 610 && i < 700) mu -= 0.0017;
  var vol = 0.0088 + (i > 600 && i < 720 ? 0.0045 : 0);
  R.push(mu + vol * gauss());
}
var win = 126, idx = N - 1, SR = [], XR = [], VO = [], full;
function calc() {
  SR = []; XR = []; VO = [];
  var s = 0, s2 = 0, k;
  for (k = 0; k < N; k++) {
    s += R[k]; s2 += R[k] * R[k];
    if (k >= win) { s -= R[k - win]; s2 -= R[k - win] * R[k - win]; }
    if (k >= win - 1) {
      var m = s / win, sd = Math.sqrt(Math.max((s2 - win * m * m) / (win - 1), 1e-12));
      var xr = (m - RFD) * 252, vo = sd * Math.sqrt(252);
      XR[k] = xr; VO[k] = vo; SR[k] = xr / vo;
    }
  }
  /* full-sample Sharpe over the displayed span */
  var fm = 0, n = N - S0, fv = 0;
  for (k = S0; k < N; k++) fm += R[k];
  fm /= n;
  for (k = S0; k < N; k++) fv += (R[k] - fm) * (R[k] - fm);
  full = (fm - RFD) * 252 / (Math.sqrt(fv / (n - 1)) * Math.sqrt(252));
}
function X(t) { return (t - S0) / (N - 1 - S0) * W; }
function Y(v) { return (YMAX - Math.max(YMIN, Math.min(YMAX, v))) / (YMAX - YMIN) * H; }
function bucket(v) { return v < 0 ? 0 : v < 1 ? 1 : v < 2 ? 2 : 3; }
function fd(t) { var x = dates[t]; return ('0' + x.getUTCDate()).slice(-2) + ' ' + MON[x.getUTCMonth()] + ' ' + String(x.getUTCFullYear()).slice(2); }
function sg(v) { return (v >= 0 ? '+' : '−') + Math.abs(v).toFixed(2); }
function pc(v) { return (v >= 0 ? '+' : '−') + Math.abs(v * 100).toFixed(2) + '%'; }
function tone(v) { return P + '-' + (v < 0 ? 'dn' : v < 1 ? 'am' : 'up'); }
var NS = 'http://www.w3.org/2000/svg', z0;
(function xaxis() {
  var xh = '';
  for (var t = S0 + 1; t < N; t++) if (dates[t].getUTCFullYear() !== dates[t - 1].getUTCFullYear()) xh += '<span style="left:' + (X(t) / W * 100).toFixed(2) + '%">' + dates[t].getUTCFullYear() + '</span>';
  q('xax').innerHTML = xh;
})();
function axes() {
  var lo = Infinity, hi = -Infinity;
  for (var t = S0; t < N; t++) { lo = Math.min(lo, SR[t]); hi = Math.max(hi, SR[t]); }
  YMIN = Math.min(-1, Math.floor(lo - 0.25)); YMAX = Math.max(3, Math.ceil(hi + 0.25)); z0 = Y(0);
  var stp = YMAX - YMIN > 8 ? 2 : 1, g = q('grid'), ya = '';
  g.innerHTML = '';
  for (var v = Math.ceil(YMIN / stp) * stp; v <= YMAX; v += stp) {
    var l = document.createElementNS(NS, 'line'), y = Y(v);
    l.setAttribute('x1', 0); l.setAttribute('x2', W); l.setAttribute('y1', y); l.setAttribute('y2', y);
    l.setAttribute('class', v === 0 ? P + '-z' : v === 1 ? P + '-g1' : v === 2 ? P + '-g2' : '');
    g.appendChild(l);
    ya += '<span style="top:' + (y / H * 100).toFixed(2) + '%">' + (v > 0 ? '+' : v < 0 ? '−' : '') + Math.abs(v).toFixed(1) + '</span>';
  }
  q('ya').innerHTML = ya;
}
function build() {
  calc(); axes();
  var ln = '', pos = '', neg = '', t;
  for (t = S0; t < N; t++) {
    var x = X(t).toFixed(2), y = Y(SR[t]);
    ln += (t === S0 ? 'M' : ' L') + x + ',' + y.toFixed(2);
    pos += ' L' + x + ',' + Math.min(y, z0).toFixed(2);
    neg += ' L' + x + ',' + Math.max(y, z0).toFixed(2);
  }
  q('ln').setAttribute('d', ln);
  q('fp').setAttribute('d', 'M0,' + z0 + pos + ' L' + W + ',' + z0 + ' Z');
  q('fn').setAttribute('d', 'M0,' + z0 + neg + ' L' + W + ',' + z0 + ' Z');
  var fy = Y(full), fl = q('full');
  fl.setAttribute('y1', fy); fl.setAttribute('y2', fy);
  var flab = q('fl'); flab.style.top = (fy / H * 100) + '%'; flab.textContent = 'FULL-PERIOD ' + sg(full);
  /* regime ribbon: merge consecutive days in the same bucket */
  var rib = '', st = S0, b0 = bucket(SR[S0]), cnt = [0, 0, 0, 0];
  for (t = S0; t <= N; t++) {
    var b = t < N ? bucket(SR[t]) : -1;
    if (t < N) cnt[b]++;
    if (b !== b0) { rib += '<rect class="' + P + '-c' + b0 + '" x="' + X(st).toFixed(2) + '" y="0" width="' + (X(t - 1) - X(st) + W / (N - S0)).toFixed(2) + '" height="6"></rect>'; st = t; b0 = b; }
  }
  q('rib').innerHTML = rib;
  var n = N - S0, arr = SR.slice(S0).sort(function (a, c) { return a - c; });
  var mean = 0; for (t = S0; t < N; t++) mean += SR[t]; mean /= n;
  var med = arr[Math.floor(n / 2)];
  var cells = [['NOW ' + { 63: '3M', 126: '6M', 252: '12M' }[win], SR[N - 1]], ['MEAN', mean], ['MEDIAN', med], ['MIN', arr[0]], ['MAX', arr[n - 1]]];
  q('kpi').innerHTML = cells.map(function (c) { return '<div><span>' + c[0] + '</span><b class="' + tone(c[1]) + '">' + sg(c[1]) + '</b></div>'; }).join('') + '<div><span>% TIME &ge;1</span><b>' + ((cnt[2] + cnt[3]) / n * 100).toFixed(0) + '%</b></div>';
  q('tm').textContent = 'TIME <0: ' + (cnt[0] / n * 100).toFixed(0) + '% · ' + win + 'D WINDOW';
  [].forEach.call(root.querySelectorAll('.' + P + '-seg button'), function (bt) { var on = +bt.getAttribute('data-w') === win; bt.classList.toggle(P + '-on', on); bt.setAttribute('aria-pressed', on ? 'true' : 'false'); });
  paint();
}
function paint() {
  var x = X(idx), cx = q('cx');
  cx.setAttribute('x1', x); cx.setAttribute('x2', x);
  var dot = q('dot'); dot.style.left = (x / W * 100) + '%'; dot.style.top = (Y(SR[idx]) / H * 100) + '%';
  q('read').innerHTML = '<b>' + fd(idx) + '</b><span>SHARPE <b class="' + tone(SR[idx]) + '">' + sg(SR[idx]) + '</b></span><span>XS RET <b class="' + P + '-' + (XR[idx] >= 0 ? 'up' : 'dn') + '">' + pc(XR[idx]) + '</b></span><span>VOL <b>' + (VO[idx] * 100).toFixed(2) + '%</b></span><span>' + fd(idx - win + 1) + ' →</span>';
}
root.querySelector('.' + P + '-seg').addEventListener('click', function (ev) { var bt = ev.target.closest('button'); if (!bt) return; win = +bt.getAttribute('data-w'); build(); });
var plots = q('plots');
function fromPointer(ev) {
  var rc = q('plot').getBoundingClientRect(); if (!rc.width) return;
  var f = Math.max(0, Math.min(1, (ev.clientX - rc.left) / rc.width));
  idx = S0 + Math.round(f * (N - 1 - S0)); paint();
}
plots.addEventListener('pointermove', fromPointer);
plots.addEventListener('pointerdown', fromPointer);
root.addEventListener('keydown', function (ev) {
  var k = ev.key, stp = ev.shiftKey ? 21 : 1, w = { '3': 63, '6': 126, '1': 252 }[k];
  if (w) { win = w; build(); }
  else if (k === 'ArrowLeft') { idx = Math.max(S0, idx - stp); paint(); }
  else if (k === 'ArrowRight') { idx = Math.min(N - 1, idx + stp); paint(); }
  else if (k === 'Home') { idx = S0; paint(); }
  else if (k === 'End') { idx = N - 1; paint(); }
  else return;
  ev.preventDefault();
});
build();

