.cpf-calendar-year-hd{display:flex;justify-content:space-between;align-items:flex-start;gap:6px;margin-bottom:4px}
.cpf-calendar-year-t{font:700 10px/1.2 system-ui,-apple-system,Segoe UI,sans-serif;color:#E4EBF7;letter-spacing:.05em;min-width:0}
.cpf-calendar-year-t b{display:block;font:500 7px/1.4 ui-monospace,Menlo,Consolas,monospace;color:#5B6883;letter-spacing:.06em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.cpf-calendar-year-seg{display:flex;border:1px solid #243047;border-radius:3px;overflow:hidden;flex:none}
.cpf-calendar-year-seg button{font:600 7px/1 ui-monospace,Menlo,Consolas,monospace;letter-spacing:.05em;color:#6B7890;background:transparent;border:0;border-left:1px solid #243047;padding:4px 5px;cursor:pointer}
.cpf-calendar-year-seg button:first-child{border-left:0}
.cpf-calendar-year-seg button:hover{color:#C9D4E8}
.cpf-calendar-year-seg .cpf-calendar-year-on{background:#1B2A45;color:#E4EBF7}
.cpf-calendar-year-lg{display:flex;gap:8px;font-size:6.8px;letter-spacing:.05em;color:#6B7890;margin:0 0 4px 26px;min-height:9px}
.cpf-calendar-year-lg i{display:inline-block;width:7px;height:6px;margin-right:3px;border-radius:1px;vertical-align:-0.5px}
.cpf-calendar-year-g{display:grid;grid-template-columns:24px 1fr;column-gap:2px}
.cpf-calendar-year-rw{grid-template-columns:26px repeat(11,minmax(0,1fr));column-gap:0;height:12px;align-items:center}
.cpf-calendar-year-ya{position:relative;height:118px}
.cpf-calendar-year-ya span{position:absolute;right:1px;font-size:6.8px;color:#5B6883;transform:translateY(-50%);white-space:nowrap}
.cpf-calendar-year-plot{position:relative;height:118px;border-left:1px solid #2A3650}
.cpf-calendar-year-gl{position:absolute;inset:0;pointer-events:none}
.cpf-calendar-year-gl i{position:absolute;left:0;right:0;height:0;border-top:1px solid #151C28}
.cpf-calendar-year-gl i.cpf-calendar-year-z{border-top:1px solid #3A4866}
.cpf-calendar-year-cols{position:absolute;inset:0;display:grid;grid-template-columns:repeat(11,minmax(0,1fr))}
.cpf-calendar-year-col{position:relative;cursor:pointer;border-radius:2px}
.cpf-calendar-year-col:hover{background:rgba(110,168,255,.05)}
.cpf-calendar-year-col.cpf-calendar-year-sel{background:rgba(110,168,255,.12);box-shadow:inset 0 0 0 1px #2A3D63}
.cpf-calendar-year-bar{position:absolute;width:34%;border-radius:1px;transform-origin:50% 100%;animation:cpf-calendar-year-grow .55s cubic-bezier(.3,.7,.2,1) both}
.cpf-calendar-year-bar.cpf-calendar-year-neg{transform-origin:50% 0}
.cpf-calendar-year-f{left:14%;background:#6EA8FF}
.cpf-calendar-year-b{left:52%;background:#8C7240}
.cpf-calendar-year-xb{left:28%;width:44%}
.cpf-calendar-year-xb.cpf-calendar-year-pos{background:#25E07A}
.cpf-calendar-year-xb.cpf-calendar-year-neg{background:#FF5C6C}
.cpf-calendar-year-pm{position:absolute;left:8%;right:8%;height:0;border-top:1.5px solid #D9C8FF;z-index:2;pointer-events:none}
.cpf-calendar-year-pd{position:absolute;left:50%;width:5px;height:5px;margin:-2.5px 0 0 -2.5px;border-radius:50%;background:#0B0F17;border:1.5px solid #D9C8FF;z-index:2;pointer-events:none}
.cpf-calendar-year-ytd .cpf-calendar-year-f,.cpf-calendar-year-ytd .cpf-calendar-year-b,.cpf-calendar-year-ytd .cpf-calendar-year-xb{opacity:.55;background-image:repeating-linear-gradient(135deg,rgba(11,15,23,.55) 0 2px,transparent 2px 4px)}
.cpf-calendar-year-rw span{text-align:center;white-space:nowrap;overflow:hidden;font-size:7px}
.cpf-calendar-year-rw .cpf-calendar-year-rl{text-align:right;font-size:6px;letter-spacing:.04em;color:#4B5772;padding-right:3px}
.cpf-calendar-year-yr span{color:#8B98B0}
.cpf-calendar-year-yr span.cpf-calendar-year-ys{color:#FFFFFF;font-weight:700}
.cpf-calendar-year-q{display:inline-block;padding:0 2px;border-radius:2px;font-size:6.5px;line-height:9px;font-weight:700;color:#0B0F17}
.cpf-calendar-year-q1{background:#25E07A}
.cpf-calendar-year-q2{background:#8FD9A8}
.cpf-calendar-year-q3{background:#F5B942}
.cpf-calendar-year-q4{background:#FF5C6C}
.cpf-calendar-year-det{display:flex;flex-wrap:wrap;gap:1px 8px;margin-top:5px;padding:4px 5px;background:#0F1420;border:1px solid #1A2230;border-radius:3px;font-size:8px;min-height:30px}
.cpf-calendar-year-det b{color:#E4EBF7;font-weight:600}
.cpf-calendar-year-sum{display:grid;grid-template-columns:repeat(4,1fr);gap:1px;margin-top:5px;background:#1A2230;border:1px solid #1A2230;border-radius:3px;overflow:hidden}
.cpf-calendar-year-sum div{background:#0B0F17;padding:3px 4px;min-width:0}
.cpf-calendar-year-sum span{display:block;font-size:6.5px;letter-spacing:.07em;color:#4B5772;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.cpf-calendar-year-sum b{display:block;font-size:9px;font-weight:600;color:#D6DFEF;text-align:right;white-space:nowrap}
.cpf-calendar-year .cpf-calendar-year-up{color:#25E07A}
.cpf-calendar-year .cpf-calendar-year-dn{color:#FF5C6C}
@keyframes cpf-calendar-year-grow{from{transform:scaleY(0)}to{transform:scaleY(1)}}
@media (prefers-reduced-motion: reduce){.cpf-calendar-year-bar{animation:none}}

