var P = 'cpf-calendar-year';
function q(s) { return root.querySelector('.' + P + '-' + s); }
/* year, fund net %, policy BM %, peer median %, peer percentile rank (1 = best) */
var YRS = [
  [2016, 9.8, 7.9, 6.4, 14], [2017, 18.2, 17.6, 15.1, 22], [2018, -2.1, -5.3, -6.8, 9],
  [2019, 18.1, 22.9, 19.7, 58], [2020, 16.7, 13.8, 12.2, 17], [2021, 14.9, 18.6, 16.4, 62],
  [2022, -9.6, -15.8, -14.1, 11], [2023, 17.3, 18.9, 15.6, 31], [2024, 15.2, 16.4, 13.0, 27],
  [2025, 13.4, 12.1, 11.2, 24], [2026, 8.7, 9.3, 7.8, 41]
];
var YTD = 2026, mode = 'a', sel = YRS.length - 2, n = YRS.length;
function sg(v, dp) { var t = Math.abs(v).toFixed(dp); return (+t === 0 ? '' : v > 0 ? '+' : '−') + t; }
function pc(v) { return sg(v, 2) + '%'; }
function bp(v) { return sg(Math.round(v * 100), 0) + 'bp'; }
function cl(v) { return P + '-' + (v >= 0 ? 'up' : 'dn'); }
function qt(p) { return p <= 25 ? 1 : p <= 50 ? 2 : p <= 75 ? 3 : 4; }
function range() { return mode === 'a' ? [-20, 25, 10] : [-6, 8, 2]; }
function render() {
  var r = range(), lo = r[0], hi = r[1];
  function Y(v) { return (hi - v) / (hi - lo) * 100; }
  var gl = '', ya = '';
  for (var v = Math.ceil(lo / r[2]) * r[2]; v <= hi; v += r[2]) {
    gl += '<i' + (v === 0 ? ' class="' + P + '-z"' : '') + ' style="top:' + Y(v).toFixed(2) + '%"></i>';
    ya += '<span style="top:' + Y(v).toFixed(2) + '%">' + (v === 0 ? '0%' : sg(v, 0) + '%') + '</span>';
  }
  q('gl').innerHTML = gl; q('ya').innerHTML = ya;
  var h = '', y0 = Y(0);
  YRS.forEach(function (y, k) {
    var cls = P + '-col' + (k === sel ? ' ' + P + '-sel' : '') + (y[0] === YTD ? ' ' + P + '-ytd' : '');
    function bar(val, c) {
      var top = Math.min(Y(val), y0), ht = Math.abs(Y(val) - y0);
      return '<i class="' + P + '-bar ' + P + '-' + c + (val < 0 ? ' ' + P + '-neg' : ' ' + P + '-pos') + '" style="top:' + top.toFixed(2) + '%;height:' + Math.max(ht, 0.6).toFixed(2) + '%;animation-delay:' + (k * 40) + 'ms"></i>';
    }
    h += '<div class="' + cls + '" data-k="' + k + '">';
    if (mode === 'a') h += bar(y[1], 'f') + bar(y[2], 'b') + '<i class="' + P + '-pm" style="top:' + Y(y[3]).toFixed(2) + '%"></i>';
    else h += bar(y[1] - y[2], 'xb') + '<i class="' + P + '-pd" style="top:' + Y(y[1] - y[3]).toFixed(2) + '%"></i>';
    h += '</div>';
  });
  q('cols').innerHTML = h;
  q('lg').innerHTML = mode === 'a'
    ? '<span><i style="background:#6EA8FF"></i>FUND</span><span><i style="background:#8C7240"></i>POLICY BM</span><span><i style="height:0;border-top:1.5px solid #D9C8FF"></i>PEER MEDIAN</span>'
    : '<span><i style="background:#25E07A"></i>FUND − BM</span><span><i style="border-radius:50%;background:#0B0F17;border:1.5px solid #D9C8FF;width:6px"></i>FUND − PEER MED</span><span>% PTS</span>';
  var yr = '<span class="' + P + '-rl"></span>', xs = '<span class="' + P + '-rl">XS BM</span>', qr = '<span class="' + P + '-rl">PEER Q</span>';
  YRS.forEach(function (y, k) {
    yr += '<span' + (k === sel ? ' class="' + P + '-ys"' : '') + '>' + (y[0] === YTD ? 'YTD' : '’' + String(y[0]).slice(2)) + '</span>';
    var d = y[1] - y[2];
    xs += '<span class="' + cl(d) + '">' + sg(d, 1) + '</span>';
    qr += '<span><b class="' + P + '-q ' + P + '-q' + qt(y[4]) + '">Q' + qt(y[4]) + '</b></span>';
  });
  q('yr').innerHTML = yr; q('xs').innerHTML = xs; q('qr').innerHTML = qr;
  [].forEach.call(root.querySelectorAll('.' + P + '-seg button'), function (b) { var on = b.getAttribute('data-v') === mode; b.classList.toggle(P + '-on', on); b.setAttribute('aria-pressed', on ? 'true' : 'false'); });
  detail();
}
function detail() {
  var y = YRS[sel], dB = y[1] - y[2], dP = y[1] - y[3];
  q('det').innerHTML = '<b>' + (y[0] === YTD ? y[0] + ' YTD' : y[0]) + '</b><span>FUND <b class="' + cl(y[1]) + '">' + pc(y[1]) + '</b></span><span>BM <b class="' + cl(y[2]) + '">' + pc(y[2]) + '</b></span><span>PEER MED <b class="' + cl(y[3]) + '">' + pc(y[3]) + '</b></span>' +
    '<span>vs BM <b class="' + cl(dB) + '">' + bp(dB) + '</b></span><span>vs PEER <b class="' + cl(dP) + '">' + bp(dP) + '</b></span><span>RANK <b>' + y[4] + ordinal(y[4]) + ' pct · Q' + qt(y[4]) + '</b></span>';
}
function ordinal(k) { var m = k % 100; if (m >= 11 && m <= 13) return 'th'; return ['th', 'st', 'nd', 'rd'][k % 10] || 'th'; }
(function summary() {
  var full = YRS.filter(function (y) { return y[0] !== YTD; }), m = full.length;
  var cf = 1, cb = 1, bat = 0, up = 0, q1 = 0, worst = full[0], best = full[0];
  full.forEach(function (y) {
    cf *= 1 + y[1] / 100; cb *= 1 + y[2] / 100;
    if (y[1] > y[2]) bat++;
    if (y[1] > 0) up++;
    if (qt(y[4]) === 1) q1++;
    if (y[1] < worst[1]) worst = y;
    if (y[1] > best[1]) best = y;
  });
  var af = (Math.pow(cf, 1 / m) - 1) * 100, ab = (Math.pow(cb, 1 / m) - 1) * 100;
  var cells = [
    [m + 'Y ANN FUND', pc(af), cl(af)], [m + 'Y ANN BM', pc(ab), cl(ab)], ['ANN XS (GEO)', bp(((1 + af / 100) / (1 + ab / 100) - 1) * 100), cl(af - ab)], ['CUM FUND', pc((cf - 1) * 100), cl(cf - 1)],
    ['BATTING vs BM', bat + '/' + m + ' · ' + Math.round(bat / m * 100) + '%', ''], ['UP YEARS', up + '/' + m, ''], ['1ST QUARTILE', q1 + '/' + m, ''], ['WORST YR · ' + worst[0], pc(worst[1]), cl(worst[1])]
  ];
  q('sum').innerHTML = cells.map(function (c) { return '<div><span>' + c[0] + '</span><b' + (c[2] ? ' class="' + c[2] + '"' : '') + '>' + c[1] + '</b></div>'; }).join('');
})();
function pick(k) {
  sel = Math.max(0, Math.min(n - 1, k));
  [].forEach.call(q('cols').children, function (e, j) { e.classList.toggle(P + '-sel', j === sel); });
  [].forEach.call(q('yr').children, function (e, j) { e.classList.toggle(P + '-ys', j - 1 === sel); });
  detail();
}
q('cols').addEventListener('click', function (ev) { var e = ev.target.closest('.' + P + '-col'); if (e) pick(+e.getAttribute('data-k')); });
root.querySelector('.' + P + '-seg').addEventListener('click', function (ev) { var b = ev.target.closest('button'); if (!b) return; mode = b.getAttribute('data-v'); render(); });
root.addEventListener('keydown', function (ev) {
  var k = ev.key;
  if (k === 'ArrowLeft') pick(sel - 1);
  else if (k === 'ArrowRight') pick(sel + 1);
  else if (k === 'Home') pick(0);
  else if (k === 'End') pick(n - 1);
  else if (k === 'a' || k === 'x') { mode = k; render(); }
  else return;
  ev.preventDefault();
});
render();
